/* Alfred University AU-ESET 301 v16.3 — preserved semantic-evidence authority.
   This layer preserves v16.1 architecture/IDs and replaces generic coverage claims
   with topic-specific teaching plus constructed-response/performance checks. */
(() => {
  const C = window.ALFRED_CURRICULUM;
  const A = window.ALFRED_ASSESSMENT;
  if (!A) return;

  const S = (domain, week, title, codes, teach, prompt, required) => ({domain:String(domain), week, title, codes, teach, prompt, required});
  const sections = [
    S(1,1,'Shock physiology, emergency response, and First Aid boundaries',
      ['1.1','1.2','1.14'],
      `Electrical injury is controlled first by removing exposure, not by rushing to touch the injured person. Shock severity depends on current magnitude, the path through the body, contact duration, frequency, skin/contact condition, and the person’s condition. Effects can range from pain and involuntary muscle contraction to burns, respiratory arrest, dangerous heart rhythms, and death. A person may be unable to release an energized conductor. If an electrical contact occurs, do not become a second victim: do not touch the person while the source may still be energized. Call emergency services, have the source disconnected by a safe method within your training and site procedure, and use CPR, an AED, bleeding/burn care, or other First Aid only to the level you are trained and authorized to provide. Electrical injury can involve hidden internal damage even when skin injury looks small, so professional medical evaluation can be necessary. For an untrained worker the correct competence is recognition and escalation: identify the emergency, keep others away, call for help, remove energy only when that can be done safely, and follow dispatcher/site instructions. This course does not authorize energized rescue or substitute for hands-on First Aid/CPR/AED training.`,
      'A coworker is motionless while still contacting equipment that may be energized. Explain the safe response sequence and why touching the person first can create a second casualty.',
      ['Recognize shock effects can include involuntary contraction, burns, respiratory or cardiac effects','Do not touch a person who may still be energized','Call emergency services and remove energy only by a safe trained method','Use CPR/AED/First Aid only within training and authorization','State that electrical injury may require medical evaluation even when external burns look limited']),
    S(1,1,'NEC awareness, overcurrent protection, and lockout/tagout',
      ['1.3','1.4','1.7','1.10.3'],
      `The National Electrical Code (NFPA 70) is primarily an installation code: it addresses how electrical systems and equipment are installed so hazards are controlled. It is not a substitute for employer safe-work procedures or the energized-work rules that apply to a technician’s task. A technician therefore follows the applicable code, listing/labeling and manufacturer instructions, and also follows workplace safety procedures. Fuses and circuit breakers protect conductors and equipment from excessive current. Replacement means matching the required device type, voltage rating, current rating, and interrupting capability; a slow-blow/time-delay fuse and a fast-acting fuse can behave very differently during normal inrush. Never bypass a protective device or substitute a larger rating merely to stop nuisance opening. Lockout/tagout controls hazardous energy before servicing: identify energy sources, shut down, isolate them, apply the authorized lock/tag, control stored energy, and verify the de-energized/zero-energy condition before work. A software Stop button, open control contact, or dark display is not proof of isolation. Only people trained and authorized under the employer’s energy-control program perform the lockout steps that require that authorization.`,
      'A fuse opens repeatedly after replacement. Describe what you must verify before installing another fuse, and explain why selecting a larger current rating or relying on a software Stop command is unsafe.',
      ['Match fuse/breaker type, voltage, current and interrupting rating','Explain time-delay versus fast-acting behavior','Do not bypass or up-rate protection to cure a fault','Describe identify-shutdown-isolate-lock/tag-control stored energy-verify sequence','Distinguish a control command from physical energy isolation']),
    S(1,1,'ESD, technician tool hazards, and PPE',
      ['1.5','1.6','1.10','1.10.1'],
      `Electrostatic discharge is a rapid transfer of charge caused by a voltage difference. A discharge too small to feel can still puncture or weaken semiconductor junctions, especially CMOS inputs. At an approved de-energized ESD workstation, control static with a verified dissipative mat, approved wrist strap/grounding system, grounded tools where specified, antistatic packaging, and handling that avoids touching contacts. ESD controls are not permission to connect yourself to hazardous energized equipment; site procedures govern when straps may be worn. Technician hazards also include damaged insulation, cracked probes, wrong meter category/rating, metal jewelry, hot soldering tools, sharp leads, batteries capable of high fault current, rotating mechanisms, and stored energy in capacitors. PPE is chosen from the actual hazard assessment: eye protection, gloves, arc-rated clothing, hearing protection, footwear, or other equipment may be required by the task and workplace. PPE is a layer of protection, not a reason to skip de-energization, guarding, isolation, correct tools, or safe distance.`,
      'You are about to handle a CMOS board at a low-voltage bench. Describe the ESD controls you would use, then name three other technician hazards that require controls different from ESD.',
      ['Explain why imperceptible ESD can damage CMOS','Name mat/strap/packaging/handling controls','State that ESD straps are governed by energized-work safety rules','Identify at least three non-ESD technician hazards','Explain that PPE follows hazard assessment and does not replace isolation or correct tools']),
    S(1,1,'RF exposure and fiber-optic hazards',
      ['1.8','1.9','1.10.2'],
      `RF exposure risk depends on frequency, transmitter power, antenna gain, duty cycle, distance, exposure duration, and whether the exposure is occupational/controlled or general/uncontrolled. Maximum Permissible Exposure (MPE) limits are therefore not one universal distance or power number. A technician follows the organization’s RF-safety program, posted boundaries, lockout/interlock rules, and the applicable FCC/OSHA/ANSI method; never defeat an interlock, stand in a restricted antenna field, or assume a transmitter is safe because the RF cannot be seen. Fiber systems create different hazards. Active fibers can carry invisible infrared light that can injure the eye, and cleaving/splicing creates tiny glass shards that can penetrate skin or eyes. Never look into a fiber or connector to see whether it is live; use a rated optical test instrument and verify the source state. Wear appropriate eye protection, keep food/drink away, cap unused ends, collect scraps in a dedicated sharps container, and clean the work area. RF and fiber both require recognizing invisible hazards, but the mechanisms and controls are different.`,
      'Compare the safety controls for an active RF transmitter site and for fiber termination. Explain why “I cannot see anything dangerous” is not a valid safety conclusion in either case.',
      ['Name the factors that determine RF exposure/MPE','Follow boundaries/interlocks/site procedures rather than using a universal safe distance','Never look into an unknown/active fiber','Identify invisible IR and glass-shard hazards','Describe fiber scrap, capping, eye-protection and test-instrument controls']),
    S(1,1,'Ladders, service vehicles, and fire classes',
      ['1.11','1.12','1.13'],
      `A ladder is equipment that must be selected and inspected for the task. Check feet, rails, rungs, locks and labels; set it on a stable surface, maintain required angle/securement for the ladder type, keep three-point control while climbing, and do not overreach. Around electrical hazards, follow the workplace rule for nonconductive ladders and minimum approach boundaries. Service vehicles add stored and moving hazards: secure ladders, batteries, tools and heavy equipment against sudden stops; preserve the driver’s view; use approved racks/tie-downs; and keep loose objects from becoming projectiles. Fire classes describe the fuel involved: A is ordinary combustibles, B flammable liquids/gases, C energized electrical equipment, D combustible metals, and K cooking oils/fats. Extinguishers are selected for the fuel and site plan. De-energizing can change the electrical aspect of a Class C incident, but a technician should use the approved extinguisher and emergency procedure and attempt firefighting only when trained, the fire is incipient/small, an escape path is maintained, and site policy permits it.`,
      'You arrive at a site with a roof ladder, a box of batteries/tools, and an electrical cabinet fire reported inside. Give the ladder/vehicle checks and the fire-class decision boundaries before you act.',
      ['Inspect/select/secure ladder and avoid electrical-conductive hazards','Secure transported loads and preserve driver visibility','Correctly identify A/B/C/D/K fire classes','Match extinguisher to fuel/site plan','State trained-response and escape/escalation boundaries']),

    S(2,2,'Atoms, charge, current, voltage, resistance, and uses of electricity',
      ['2.1','2.4','2.6'],
      `Atoms contain positively charged protons, neutral neutrons, and negatively charged electrons. Electronics is primarily concerned with how charge carriers move or are redistributed in materials. One coulomb is a quantity of charge; one ampere is one coulomb per second. Current is therefore a rate of charge flow, while voltage is energy difference per unit charge between two points. Resistance describes how strongly a material/device opposes current for a given applied voltage. These terms are not interchangeable: a 5 V source can exist with nearly zero current when the circuit is open, and a low resistance can allow very large current if the source can supply it. Electrical energy is used for heating, light, motion, computation, communication, sensing, storage and conversion. A technician uses the same quantities whether the device is a simple resistor circuit or an embedded board: identify the source/reference, predict current paths, check voltage differences, and verify power/rating limits.`,
      'Explain why a 5 V source can measure 5 V while almost no current flows, then relate current in amperes to charge in coulombs.',
      ['Define proton/electron charge roles at introductory level','State 1 A = 1 C/s','Distinguish voltage, current and resistance','Explain an open-circuit voltage example','Name several practical uses/conversions of electrical energy']),
    S(2,2,'Electromagnetism and induction',
      ['2.2','2.2.1','2.2.2','2.3'],
      `Electric current produces a magnetic field around a conductor; coiling the conductor concentrates the field and a ferromagnetic core can increase magnetic flux. Permanent magnets provide a field without an energizing coil, while electromagnets create a controllable field from current. The relationship works in the other direction too: a changing magnetic flux through a conductor induces voltage. The key word is changing—steady magnetic flux alone does not continuously induce voltage in a stationary loop. These principles explain relays and solenoids (current creates force), transformers (changing flux couples energy between windings), motors (current and magnetic fields create torque), generators (mechanical motion changes flux and induces voltage), speakers, microphones and inductive sensors. Polarity/direction follows the direction of current and field change, which is why reversing current can reverse magnetic force and why transformer/generator waveforms track changing flux.`,
      'Compare an electromagnet, transformer, motor, and generator by identifying where current creates magnetism and where changing magnetism creates voltage.',
      ['Explain current-created magnetic field','Differentiate permanent and electromagnet fields','Explain changing flux induces voltage','Connect principle to relays/transformers/motors/generators','State that steady unchanging flux does not continuously induce a voltage in a stationary loop']),
    S(2,2,'Motors and generators as reciprocal energy converters',
      ['2.5','2.5.1'],
      `A motor converts electrical input into mechanical torque. Current in a conductor within a magnetic field experiences force; practical motors arrange windings and magnetic fields so the forces create rotation. Commutation may be mechanical (brushes/commutator) or electronic, depending on motor type. As speed rises, many motors develop back EMF that opposes the applied voltage, which helps explain high starting current when speed and back EMF are initially low. A generator performs the reciprocal conversion: mechanical motion changes magnetic flux through windings and induces an electrical voltage/current when a circuit is connected. Real machines also have copper loss, core loss, friction, heating and saturation limits, so electrical input and mechanical output are not identical. CETa points to the EM5 competencies for deeper electromechanical detail; for this course, the required foundation is to trace energy direction, field/current interaction, commutation, back-EMF/start-current behavior, and generator induction.`,
      'A DC motor draws much more current at stall than while spinning normally. Explain this using back EMF, then explain how rotating a generator shaft produces electrical output.',
      ['Trace motor electrical-to-mechanical conversion','Explain starting/stall current with back EMF','Identify commutation role at a basic level','Trace generator mechanical-to-electrical conversion','Recognize real-machine losses and limits']),
    S(2,2,'Resistive, capacitive, inductive and impedance behavior',
      ['2.7','2.8','2.9','2.10','2.11'],
      `Resistors may use carbon/metal films, wirewound elements, semiconductor thermistors and other materials chosen for value range, power, stability, noise and temperature behavior. Capacitors store energy in an electric field; common constructions include ceramic, film and electrolytic devices, with polarity applying to many electrolytics. Inductors store energy in a magnetic field; turns, coil geometry, wire resistance and core material affect inductance and losses. Resistance is the real, dissipative opposition measured in ohms. Reactance is frequency-dependent opposition from capacitance or inductance: XC = 1/(2πfC) falls as frequency rises, while XL = 2πfL rises. Impedance combines resistance and reactance and therefore includes both magnitude and phase. In AC circuits, voltage/current phase relationships matter: ideal resistor V and I are in phase, ideal inductor current lags voltage, and ideal capacitor current leads voltage.`,
      'At two different frequencies, compare a resistor, capacitor, and inductor. State what happens to XC and XL and why impedance cannot always be treated as simple resistance.',
      ['Differentiate common R/C/L construction and purpose','State energy-storage roles of C and L','Use XC and XL relationships','Distinguish resistance, reactance and impedance','State basic R/L/C phase relationships']),
    S(2,2,'Sources, AC measures, duty cycle, pulse width, Ohm’s law, and power',
      ['2.12','2.12.1','2.12.2','2.13','2.13.1','2.14'],
      `Sources may be DC (battery, regulated supply, rectified/regulator output, photovoltaic or other generation) or AC (utility/alternator/signal generator). For a symmetric sine wave, peak is the maximum excursion from the reference, peak-to-peak is twice the peak, and Vrms = Vpk/√2; RMS is the DC-equivalent heating measure for a resistive load. A pulsed DC waveform alternates between levels. Pulse width is the time a pulse remains in its active state; period is the time for one full cycle; duty cycle is pulse width/period × 100%. At 1 kHz, period is 1 ms; a 250 µs high pulse has 25% duty cycle. Ohm’s law V=IR can be rearranged to I=V/R and R=V/I. Power can be found from P=VI and, for resistive cases, P=I²R or V²/R. Correct work retains units/prefixes and checks source/component ratings rather than stopping at arithmetic.`,
      'A 1 kHz, 3.3 V pulse is high for 200 µs each cycle and drives a 330 Ω resistive load when high. Find period, duty cycle, high-state current, and high-state power.',
      ['Calculate 1 ms period at 1 kHz','Calculate 20% duty cycle','Use I=V/R with correct units','Use P=VI or V²/R','Distinguish peak/peak-to-peak/RMS from pulse width/duty cycle']),

    S(3,7,'Resistor families, markings, thermistors, and potentiometers',
      ['3.1','3.1.1','3.1.2','3.1.3','3.1.4'],
      `Fixed resistors include carbon-film, metal-film and wirewound constructions. Metal film is often chosen for stability/low noise; wirewound parts handle higher power but may have inductance; thermistors intentionally change resistance with temperature. Potentiometers have two end terminals and a movable wiper, allowing them to act as a three-terminal voltage divider; rheostats use the wiper plus one end as a variable resistance. Color bands or printed/SMD codes identify nominal value and tolerance, but the exact marking system depends on package. For a lightly loaded potentiometer, Vwiper = Vin × Rbottom/(Rtop+Rbottom), where the resistances are the two sections split by the wiper. Loading the wiper changes the ratio because the load is in parallel with one section. NTC thermistors decrease resistance as temperature increases; PTC devices increase. They appear in sensing, inrush control and protection.`,
      'A 10 kΩ potentiometer on 5 V has 4 kΩ from ground to the wiper and 6 kΩ from wiper to 5 V. Predict the unloaded wiper voltage and explain how a heavy load on the wiper changes it.',
      ['Differentiate carbon-film, metal-film, wirewound, thermistor, pot and rheostat roles','Explain resistor markings/color code purpose and tolerance','Distinguish NTC and PTC behavior','Calculate unloaded potentiometer divider voltage','Explain loading changes divider ratio']),
    S(3,7,'Capacitors: type, variable capacitance, charge, and coulombs',
      ['3.2','3.2.1','3.2.2'],
      `A capacitor stores separated charge in an electric field between conductive plates separated by a dielectric. Ceramic capacitors are common for decoupling/high-frequency work, film capacitors for stable timing/filtering, and electrolytics for larger capacitance/energy storage; many electrolytics are polarized. Capacitance can be varied mechanically by changing plate overlap or spacing, electronically with voltage-dependent devices such as varactors, or functionally by switching capacitor banks. Charge follows Q = C×V: one farad stores one coulomb per volt. A 100 µF capacitor at 5 V stores Q = 100×10⁻⁶ F × 5 V = 500 µC. Charge is not the same as current; current is the rate at which charge changes or flows. Voltage, ESR, temperature and ripple-current ratings matter in real parts.`,
      'Calculate the charge on a 47 µF capacitor at 12 V, then identify two ways a circuit can obtain variable capacitance and one reason capacitor polarity/rating matters.',
      ['Use Q=CV with coulombs','Distinguish charge from current','Identify ceramic/film/electrolytic uses','Describe mechanical/electronic/switched variable capacitance','Recognize polarity/voltage/ESR/ripple constraints']),
    S(3,7,'Inductors and transformers: construction, cores, turns, and laminations',
      ['3.3','3.3.1','3.4','3.4.1','3.4.2'],
      `Inductance is increased by more turns, larger magnetic coupling area and suitable high-permeability core material; it is reduced by fewer turns, air gaps and geometries with weaker coupling. Wire gauge affects winding resistance/current capacity, while coil diameter/length and turn spacing affect inductance and parasitics. Air-core inductors avoid magnetic saturation and can work well at RF; ferrite cores offer high permeability and low eddy-current loss at many high frequencies; laminated steel cores are common at lower power frequencies. Thin insulated laminations interrupt circulating eddy-current paths, reducing core heating compared with a solid conductive core. A transformer uses changing flux to couple windings. Ideally Vsecondary/Vprimary = Nsecondary/Nprimary; stepping voltage up trades current down for roughly conserved power before losses, and vice versa. Isolation, impedance matching, current sensing and signal coupling are other transformer uses.`,
      'Explain why a 60 Hz power transformer commonly uses a laminated core, then predict whether voltage rises or falls when the secondary has twice the primary turns.',
      ['Explain effects of turns/core/wire geometry','Differentiate air/ferrite/laminated core roles','Explain laminations reduce eddy-current loss','Use transformer turns/voltage ratio','Recognize step-up/down trades voltage/current rather than creating power']),
    S(3,7,'Transistors: BJT, JFET, MOSFET, CMOS, IGBT, and Darlington behavior',
      ['3.5','3.5.1','3.5.2','3.5.3'],
      `A BJT controls collector current with base-emitter junction bias and base current; NPN and PNP devices use opposite polarities. Beta (β) is a current-gain ratio IC/IB in a given operating condition, while alpha (α) relates IC to emitter current; neither is a fixed universal constant. JFETs and MOSFETs are field-effect devices controlled primarily by gate voltage. Enhancement MOSFETs normally require gate drive to form/enhance a conducting channel; depletion devices conduct at zero gate bias and are reduced/enhanced by gate bias depending on type. VGS(th) only marks the onset of a specified small current, so it is not the voltage that guarantees low on-resistance. CMOS describes complementary MOS technology used extensively in logic/ICs. IGBTs combine MOS-like gate control with bipolar conduction and are common in higher-voltage/power switching. Darlington pairs cascade BJTs for high effective current gain at the cost of higher saturation voltage and slower behavior. Bias analysis begins with device polarity, terminal voltages, expected region (cutoff/active/saturation or off/linear/on), and datasheet limits.`,
      'A 3.3 V MCU drives an N-channel MOSFET whose datasheet lists VGS(th)=2 V but specifies RDS(on) only at 4.5 V. Explain why threshold voltage does not prove the device is fully on and compare that reasoning with a BJT base-drive check.',
      ['Differentiate BJT and FET control mechanisms','Explain NPN/PNP polarity at a basic level','Define beta and alpha as operating-condition ratios','Differentiate enhancement/depletion MOSFET behavior','Explain VGS(th) is not an RDS(on) guarantee','Identify CMOS, IGBT and Darlington roles']),
    S(3,7,'SCR/DIAC/TRIAC and diode families',
      ['3.6','3.6.1','3.6.2','3.7','3.7.1','3.7.2','3.7.3'],
      `A diode conducts primarily in one direction once forward biased and blocks reverse voltage until leakage/breakdown limits are reached. Silicon and germanium diodes differ in forward behavior; Schottky diodes often have lower forward drop and fast switching; LEDs emit light; photodiodes respond to light; Zeners are designed to operate in controlled reverse breakdown. For a diode circuit, compute source/resistor current, diode voltage and power, then verify reverse-voltage/current/power ratings. A Zener regulator uses a current-limiting element so the Zener can hold approximately its rated voltage while staying within current/power limits. SCRs, TRIACs and DIACs are multi-junction switching devices. An SCR is a latching unidirectional controlled rectifier; a gate pulse can trigger it and it remains on until current falls below holding current. A TRIAC controls AC in both polarities; a DIAC is often used as a bidirectional trigger device. They differ from ordinary transistors because latching/commutation behavior is central to operation.`,
      'Choose between a Schottky diode, Zener, SCR, TRIAC and photodiode for five stated applications, and explain the key operating behavior that makes each choice appropriate.',
      ['Differentiate silicon/germanium/Schottky/LED/photo/Zener roles','Calculate diode current/power and check ratings','Explain Zener regulator current limiting','Explain SCR gate trigger and latching/holding current','Differentiate TRIAC bidirectional AC control and DIAC triggering']),
    S(3,7,'Integrated circuits and relay types including solid-state relays',
      ['3.8','3.9','3.9.1','3.9.2','3.9.3'],
      `An integrated circuit contains many devices and interconnections in one package; the technician identifies the exact part number, package orientation, pin 1, power/reference pins, inputs/outputs and any exposed pad or special pins from the datasheet before probing. Microprocessors and microcontrollers integrate CPU logic and may include memory/peripherals. A mechanical relay energizes a coil to move contacts. Schematics distinguish the coil from normally open (NO) and normally closed (NC) contacts; “normal” means the de-energized coil state. Mechanical relays provide physical contact isolation but have wear, bounce, coil current and switching-speed limits. A solid-state relay uses semiconductor switching and has no moving contacts; it can be faster/quieter and have long cycle life, but may have off-state leakage, on-state voltage drop/heating, minimum load or AC/DC restrictions and failure modes unlike a mechanical contact. Neither type is universally interchangeable: voltage/current type, isolation rating, inrush, switching frequency and load character matter.`,
      'Given a relay datasheet and schematic, identify coil, NO and NC pins, then compare what changes if the design substitutes a solid-state relay for a mechanical relay.',
      ['Identify IC pinout/orientation/power/reference from datasheet','Identify relay coil, NO and NC contacts','Define normal state as de-energized coil state','Compare mechanical wear/bounce/coil behavior with SSR leakage/drop/heating','Check load type and ratings before substitution']),

    S(4,2,'Series/parallel DC and AC networks, KCL/KVL, and resistive calculations',
      ['4.1','4.2','4.3','4.4','4.10','4.17'],
      `In a series path the same current passes through each element; in parallel branches the same two node voltages appear across every branch. For resistors, series values add and parallel conductances add; KCL states that signed current entering/leaving a node balances, and KVL states that signed voltage changes around a closed loop sum to zero. AC circuits use the same conservation laws, but R, L and C may introduce frequency-dependent impedance and phase. Do not call parts “series” merely because they are drawn beside each other: they must share a node with no other current path between them. A voltage divider is a series application; current division is a parallel effect. A technician uses these rules to predict node/branch values before measurement and to recognize impossible readings.`,
      'Solve a mixed series/parallel resistor network using equivalent resistance and KCL/KVL, then explain what changes conceptually when an inductor or capacitor replaces one resistor in an AC circuit.',
      ['Identify true series and parallel topology','Calculate equivalent resistance/voltage drop/branch current','Apply KCL and KVL with signs','Explain same conservation laws apply in AC with impedance/phase','Use predictions as troubleshooting boundaries']),
    S(4,2,'Oscillators, multivibrators, and phase-locked loops',
      ['4.5','4.6','4.12'],
      `An oscillator produces a periodic signal from DC power by using gain plus frequency-selective positive feedback or another regenerative mechanism. A crystal oscillator uses the piezoelectric resonance of quartz to provide a highly stable frequency-selective element. Multivibrators are switching/timing circuits: astable has no stable state and free-runs, monostable has one stable state and produces a timed pulse when triggered, and bistable has two stable states and acts as a latch/flip-flop. A phase-locked loop (PLL) is a feedback system built from a phase/frequency detector, loop filter, voltage- or digitally-controlled oscillator and often a divider. The detector compares reference and feedback phase/frequency; the filtered error steers the oscillator until the feedback tracks the reference. Dividers let the output lock at a multiple of the reference. PLLs are used for frequency synthesis, clock generation/recovery, tone/demodulation and stable tuning. Lock range, capture behavior, loop bandwidth and noise/jitter tradeoffs matter.`,
      'Draw a PLL block diagram and explain what each block does while the loop moves from an unlocked frequency to lock. Then distinguish astable, monostable, and bistable multivibrators.',
      ['Explain oscillator purpose and crystal stability role','Differentiate astable/monostable/bistable','Identify PLL detector, loop filter, controlled oscillator and divider','Explain negative-feedback locking process','Name PLL applications such as synthesis/clock recovery/tuning']),
    S(4,2,'Reactance class, resonance, rectangular/polar form, bandwidth and Q',
      ['4.7','4.8','4.9','4.15'],
      `A circuit is described as predominantly resistive, inductive or capacitive according to its impedance and phase behavior at the frequency of interest. Reactance is represented on the imaginary axis: +jX for inductive reactance and -jX for capacitive reactance, while resistance is on the real axis. Rectangular impedance is R+jX; polar form expresses magnitude and phase angle. Series resonance occurs when XL and XC cancel, giving an ideal minimum impedance near f0 = 1/(2π√LC); parallel resonance produces a high input impedance in the idealized case. Real resistance limits the response. Quality factor Q describes the sharpness/energy-storage-to-loss relationship; for a resonant response, higher Q generally means narrower bandwidth, and a common relationship is Q≈f0/BW for suitable resonant circuits.`,
      'For an RLC circuit, calculate resonant frequency, identify whether net reactance is inductive or capacitive below/above resonance, and convert one simple R+jX impedance to magnitude/phase.',
      ['Use f0=1/(2π√LC)','Explain XL/XC cancellation at resonance','Use rectangular R+jX representation','Convert conceptually between rectangular and polar form','Relate higher Q to narrower bandwidth in the applicable resonant model']),
    S(4,2,'Filters, integrators/differentiators, and wave shaping',
      ['4.11','4.13','4.14'],
      `Filters intentionally pass some frequency ranges while attenuating others: low-pass, high-pass, band-pass and band-stop/notch are the basic families. RC/RL networks create first-order frequency-dependent division; active filters add gain/buffering. An integrator produces an output related to the time integral of the input over its valid frequency range, while a differentiator responds to rate of change; real circuits limit gain/bandwidth so noise and saturation do not dominate. Wave-shaping circuits alter amplitude or timing rather than simply selecting frequency. Clippers limit portions of a waveform, clampers shift DC level, rectifiers enforce polarity, Schmitt triggers add hysteresis to clean slow/noisy edges, and pulse-shaping/one-shot circuits create defined pulses. Correct analysis names the intended input range, frequency range and device limits rather than assuming ideal behavior everywhere.`,
      'Classify five circuits as low-pass/high-pass/band-pass/notch, integrator/differentiator, clipper/clamper, or Schmitt-trigger wave shaper and explain the observable output change each produces.',
      ['Identify four primary filter families','Explain integrator versus differentiator behavior','Distinguish clipping from clamping','Explain Schmitt-trigger hysteresis purpose','Recognize real bandwidth/saturation/noise limitations']),
    S(4,2,'Piezoelectric effect and technician applications',
      ['4.16'],
      `Piezoelectric materials couple mechanical strain and electric charge. In the direct effect, applying force/strain to the material produces an electrical charge/voltage; this is used in vibration, knock, pressure and impact sensing. In the inverse effect, applying an electric field causes a small mechanical deformation; this is used in buzzers, ultrasonic transducers and precision actuators. Quartz also behaves piezoelectrically, which is why a crystal can form a mechanically resonant, electrically coupled frequency reference. Piezo devices can produce surprisingly high open-circuit voltages from impact even though available energy is small, and their source impedance/capacitance affect measurement. The key distinction is conversion direction: mechanical-to-electrical for sensing, electrical-to-mechanical for actuation.`,
      'Explain both the direct and inverse piezoelectric effects and give one sensing, one actuation, and one frequency-control application.',
      ['Define direct mechanical-to-electrical effect','Define inverse electrical-to-mechanical effect','Name realistic sensor and actuator examples','Connect quartz crystal resonance to piezoelectric coupling','Recognize high source impedance/measurement considerations'])
  ];

  const moreSections = [
    S(5,12,'Solder safety, fumes, splatter, flux, and alloy choice',
      ['5.1','5.2','5.3','5.4','5.5'],
      `Soldering hazards include hot iron tips, molten solder, hot components, splatter, fumes, sharp leads and contamination from lead-bearing alloys. Keep the iron in a stable holder, keep combustibles away, use eye protection where splatter is possible, and treat the work as hot until proven otherwise. Soldering fumes are primarily heated flux decomposition products; local ventilation/fume extraction controls inhalation. Lead exposure is mainly a contamination/ingestion problem from handling lead-bearing solder, so wash hands before eating or touching food and keep the bench clean; do not rely on smoke as an indicator of lead vapor. Flux removes oxides and promotes wetting. Rosin/no-clean/water-soluble chemistries have different process and cleaning requirements; use only material compatible with the assembly and procedure. Solder alloy is chosen by process temperature, reliability, compatibility and environmental requirement. Lead-free alloys generally melt at higher temperatures than traditional tin-lead alloys, so dwell time and thermal damage still require control. Splatter is reduced by clean/dry surfaces, proper tip temperature, correct solder feed and avoiding trapped moisture or excessive flux.`,
      'Write a safe solder-bench setup and explain separately how you control burn/fire risk, flux fumes, lead contamination, and splatter. Then state why flux and alloy selection are process decisions rather than interchangeable consumables.',
      ['Identify hot-tool/fire/splatter controls','Distinguish flux fumes from lead contamination route','Require hand washing/clean bench for lead-bearing solder','Explain flux removes oxides and improves wetting','Explain alloy/process temperature/compatibility tradeoffs']),
    S(5,12,'Heat shunts, cold joints, and good mechanical/electrical connections',
      ['5.6','5.7','5.8'],
      `Heat-sensitive components can be protected by controlling iron temperature, contact time, thermal mass and, where appropriate, a clip-on heat shunt between the joint and component body. A cold or disturbed solder joint forms when surfaces never reach the proper wetting temperature, are oxidized/contaminated, have inadequate flux, or move while the solder solidifies. It often looks dull, lumpy or poorly flowed, but appearance alone is not enough—inspect wetting and joint geometry and verify function. A good connection begins with sound mechanical placement, clean metallization, correct lead/pad contact, proper heating of the joint (not just the solder), complete wetting, controlled solder amount and no unintended bridges. Electrical quality means low-resistance stable connection without shorts; mechanical quality means the joint is not carrying loads it was never intended to support. Excess heat can lift pads, damage insulation or components and dissolve plating, so “more heat” is not a universal repair.`,
      'Compare a properly wetted through-hole joint with a cold/disturbed joint and an overheated joint. For each failed condition, identify the likely cause and the correct repair approach.',
      ['Explain when/how a heat shunt may protect a component','Identify causes of cold/disturbed joints','Describe wetting and joint-geometry indicators','Distinguish mechanical support from electrical continuity','Recognize overheating/pad-lift/bridge risks']),
    S(5,12,'SMT/BGA handling and PCB pad/trace/PTH repair boundaries',
      ['5.8.1','5.8.2'],
      `Surface-mount parts and printed-circuit features are small enough that ESD, contamination, mechanical force and uncontrolled heat can create damage that is difficult to see. Handle boards by edges, use ESD controls, protect gold contacts from oils/abrasion, use suitable magnification and tools, and verify component orientation/polarity. BGA packages place solder joints under the package; inspection/rework normally requires controlled equipment, profiles and trained procedures rather than hand-heating an inaccessible joint. Pad, plated-through-hole and trace repair begins by identifying exactly what has separated or opened, removing damage without enlarging it, restoring the required conductor/land with an approved repair method, anchoring it so normal mechanical load does not pull it free, and inspecting/testing continuity plus isolation from adjacent conductors. A lifted pad is not repaired by bridging randomly to any convenient copper. The repair must preserve the intended net, clearance, mechanical stability and, where relevant, high-frequency behavior.`,
      'A small SMT pad lifts during rework and the component is part of a high-speed signal net. Describe what you must determine before repairing it and why a random wire bridge is not an automatically acceptable repair.',
      ['State ESD/handling/magnification/orientation controls for SMT','Explain why BGA rework requires controlled process/equipment','Distinguish pad, PTH and trace damage','Require restoration of correct net/clearance/mechanical stability','Verify continuity and isolation after repair']),
    S(5,12,'Desoldering principles, equipment care, and solder wick',
      ['5.9','5.10','5.11','5.12'],
      `Desoldering succeeds when old solder is heated only long enough to reflow and is then removed without prying on a still-bonded lead or overheating the pad. Common tools include a manual spring pump, vacuum desoldering station/gun, hot-air/rework tools for appropriate SMT work, and solder wick. Keep tips clean/tinned, filters/nozzles maintained, and tools at the temperature and airflow specified for the assembly. Solder wick is fine copper braid that uses capillary action to absorb molten solder. Place fresh flux or a small amount of fresh solder when needed to improve heat transfer, lay the wick on the joint, place the iron on top of the wick, allow solder to flow into the braid, then lift iron and wick together before the joint freezes. Use a fresh section for the next removal. Do not scrub the pad, pull while solder is solid, or dwell until the laminate/pad lifts. After removal, inspect the pad/PTH, clean as required and verify the electrical result.`,
      'Describe the correct sequence for using solder wick on a through-hole or pad joint and name three mistakes that can lift or damage the pad.',
      ['Explain reflow-before-removal principle','Name pump/vacuum/hot-air/wick tool roles','Explain capillary action of solder wick','Describe flux/fresh-braid/heat/lift-together sequence','Identify prying, scrubbing and excessive dwell as damage risks']),

    S(6,13,'Symbols, schematic/wiring/block diagrams, drafting conventions, and IC pinouts',
      ['6.1','6.3','6.5','6.10'],
      `A schematic shows electrical function and connectivity rather than physical placement; a wiring diagram emphasizes actual terminals, wire paths or harness connections; a block diagram suppresses detail to show functional stages and signal/energy flow. Symbols communicate device type and terminal relationships, but the exact component value, reference designator and pin numbers still matter. Drafting conventions such as reference designators, net labels, junction dots, connector pin numbers, power/ground symbols, sheet references and consistent signal direction reduce ambiguity. Crossing lines are not automatically connected—look for the drawing convention/junction indication. ICs require exact package and datasheet pinout: pin 1/orientation, VCC/VDD, ground/reference, inputs, outputs, enable/reset and special pins can vary even when package shapes look similar. Never transfer a pinout from a “similar looking” IC without verifying the exact part/revision.`,
      'Given the same circuit as a block diagram, schematic, and wiring diagram, explain what question each representation answers best, then identify the minimum pinout information needed before probing an IC.',
      ['Differentiate block, schematic and wiring diagram purposes','Identify common symbol/net/junction/reference conventions','Explain drawing clarity/drafting discipline','Require exact IC part/package/pin-1 verification','Identify power/ground/input/output/control pins before probing']),
    S(6,13,'Block diagrams, test points, signal tracing, and schematic fault location',
      ['6.2','6.4','6.6','6.8'],
      `Troubleshooting begins by turning the product into functional stages: source/power, input conditioning, processing, drivers and output are common examples. A block diagram helps choose boundaries; the schematic provides component-level paths. Test points are deliberately accessible nodes chosen because their expected voltage, waveform, logic state or signal can prove whether a stage is operating. Signal tracing applies a known input, predicts what should appear at successive points, and finds the first boundary where expected behavior disappears or changes incorrectly. Tracing can proceed input-to-output, output-to-input or by half-split depending on access and risk. The goal is not to measure every point; it is to choose a point whose possible outcomes separate hypotheses. Always preserve common reference/ground and loading limits. Once the first bad boundary is located, the schematic narrows the suspect components/connections between the last-good and first-bad nodes.`,
      'A receiver has correct power and input signal but no output. Build a block-level signal-tracing plan with three test points and explain how the first bad boundary narrows the fault region.',
      ['Use block diagram to identify functional stages','Explain why test points are placed at meaningful boundaries','Describe forward/backward/half-split tracing','Use predicted signal at each point','Translate last-good/first-bad boundary back to schematic suspects']),
    S(6,13,'Building wiring awareness and flowcharts',
      ['6.7','6.9'],
      `Electronics technicians often interface equipment with building power, grounding, branch circuits, receptacles, low-voltage pathways and communications cabling. They need enough premises-wiring awareness to recognize source voltage, grounding/bonding context, breaker/branch identity, receptacle condition, separation requirements and when work belongs to a qualified electrician. This course does not authorize mains installation or energized premises work. Flowcharts are different from schematics: they represent decisions, sequence and process state using start/end, action and decision branches. A flowchart can describe a troubleshooting procedure, boot sequence or test algorithm even when no electrical connection is shown. Use a schematic to understand where current/signal can travel and a flowchart to understand what action or decision happens next.`,
      'Explain why a technician troubleshooting a rack-powered product needs premises-wiring awareness but should not treat that as authorization to modify mains wiring. Then turn a three-step fault procedure into a flowchart.',
      ['Recognize source/ground/branch/receptacle context','State electrician/energized-work boundary','Distinguish electrical connectivity from procedural sequence','Use start/action/decision flowchart logic','Choose schematic vs flowchart for the question asked']),

    S(7,19,'Wire construction, gauge, and identification',
      ['7.1','7.2','7.4'],
      `Wire and cable differ by conductor material, solid/stranded construction, insulation/jacket, shielding, twist and intended environment. Stranded wire tolerates flexing better; solid conductors hold shape and are common in fixed wiring/board work. American Wire Gauge is inverse: a smaller AWG number means a larger conductor diameter/cross-section and generally lower resistance/higher current capacity when installation conditions are comparable. Gauge selection also depends on insulation temperature, bundle/ambient conditions, length/voltage drop, connector limits and code/application requirements. Communications cable identification includes pair/category and pinout conventions; UTP uses twisted pairs to improve balanced-noise rejection, while shielded cable adds a conductive screen that must be terminated/bonded according to the system design. Never infer allowable current from gauge alone without the governing application.`,
      'Compare #18 and #24 AWG conductors for resistance/current/connector implications and explain why the larger conductor is represented by the smaller AWG number.',
      ['Describe solid vs stranded construction','Explain inverse AWG numbering','Relate gauge to resistance/current/voltage-drop constraints','Identify twisted-pair/shielding roles','State that application/code/temperature/connector conditions affect allowable use']),
    S(7,19,'Coax, copper pairs, fiber, impedance, and termination',
      ['7.3','7.5','7.6','7.6.1','7.7'],
      `Coaxial cable uses a center conductor, dielectric, surrounding shield and outer jacket. That geometry plus dielectric determines characteristic impedance, commonly 50 Ω for many RF systems and 75 Ω for many video/CATV systems. Characteristic impedance is not the same as the DC resistance measured end-to-end. Twisted copper pair carries balanced signals whose performance depends on pair geometry/twist and controlled termination. Fiber carries light rather than electrical current and is immune to ordinary electromagnetic pickup but has optical-loss, bend and connector-cleanliness constraints. At high frequencies, mismatched impedance or poor termination creates reflections, ringing and standing waves even when a DC continuity test passes. Maintaining cable geometry, connector type and specified termination is therefore part of preserving signal integrity.`,
      'A coax run passes a DC continuity test but shows severe ringing at high frequency. Explain why this can happen and what cable/termination characteristics you would investigate.',
      ['Identify coax center/dielectric/shield/jacket construction','Distinguish characteristic impedance from DC resistance','Differentiate copper/coax/fiber signal media','Explain mismatch/reflection from improper termination','Explain why continuity alone does not prove high-frequency/optical integrity']),
    S(7,19,'Bonding, splicing, crimping, and cable preparation',
      ['7.8','7.9','7.9.1','7.12','7.13'],
      `Cable shields and bonds provide controlled reference, fault/noise paths and electromagnetic containment when applied according to the system design. A shield connection that is too long, corroded or landed at the wrong point can perform poorly at high frequency. Copper/coax splicing requires the correct connector or splice method, preserved conductor/shield geometry, strain relief and inspection. Fiber splices are commonly fusion splices (controlled arc joins prepared fiber ends) or mechanical splices (aligned ends held by a precision fixture/index-matching system); both require clean, properly cleaved fiber. Crimp quality depends on matching terminal, conductor gauge and crimp tool/die, stripping the correct length without nicking strands, placing conductor/insulation correctly, completing the full tool cycle and performing visual/pull/electrical checks. The wrong die or over/under-strip can create intermittent faults that continuity may miss under motion.`,
      'Describe a valid copper crimp process and compare a fusion fiber splice with a mechanical fiber splice. Include the evidence that would make each termination defensible.',
      ['Explain bonding/shield purpose and high-frequency quality concerns','Differentiate copper/coax splice requirements','Differentiate fusion and mechanical fiber splices','Match conductor/terminal/tool/die and strip length','Require visual/pull/electrical or optical verification']),
    S(7,19,'Cable testing, dB loss, connectors, and defects',
      ['7.10','7.11'],
      `Cable tests must match the property being verified. Continuity/resistance tests find opens, shorts and gross connection problems in copper/coax but do not prove bandwidth, impedance or crosstalk. TDR-type methods locate impedance discontinuities by reflection. Fiber power meters/light sources measure insertion loss; OTDR methods can locate events and distance-dependent loss. Decibels express ratios: for power, dB = 10 log10(P2/P1); a negative insertion-loss result means less delivered power. Connector defects include bent/recessed pins, poor shield contact, contamination, incorrect keying, damaged latch/strain relief, excessive untwist, end-face contamination/scratches and wrong connector/cable impedance. A technician records source/reference level, test configuration and acceptance limit so a dB number can be reproduced.`,
      'Choose the appropriate test for (a) copper open, (b) coax impedance discontinuity, (c) fiber insertion loss, and (d) fiber event location, then explain what a -3 dB power change means qualitatively.',
      ['Match continuity/TDR/light-source-power-meter/OTDR to purpose','Use 10log power-ratio concept','Explain insertion loss sign/meaning','Identify common connector/termination defects','Record reference level/configuration/acceptance limit']),

    S(8,3,'Analog/digital meters, construction, safety, loading, and leads',
      ['8.1','8.2','8.3','8.4','8.6'],
      `An analog meter movement responds to current and uses resistors/shunts/rectification to create ranges; a digital multimeter converts an input through protection/ranging and an ADC to a numeric display. Voltage mode presents high input impedance and is connected in parallel. Current mode routes current through a low-value shunt/fuse and is inserted in series; placing a current-configured meter across a source can create a dangerous short. Resistance/continuity applies an internal test source and belongs on a de-energized circuit. Meter loading occurs because the instrument is not infinite impedance: a low input resistance can pull a high-impedance node away from its normal voltage. Safety means correct category/voltage/current rating, intact case/leads/fuses, correct jack and mode, and staying within the task’s permitted energy level. Test leads are equipment: inspect insulation, finger guards, shrouds and tips, and replace damaged leads rather than taping over unsafe damage.`,
      'Explain the internal/connection difference among voltage, current and resistance modes and predict the error produced by measuring a very high-impedance divider with a low-input-resistance meter.',
      ['Differentiate analog movement and digital ADC concept','Explain divider/shunt/protection roles','State parallel voltage vs series current vs de-energized resistance connection','Explain meter loading','Include CAT/rating/jack/lead/fuse inspection']),
    S(8,3,'Signal generators, frequency counters, RCL substitution, and ESR meters',
      ['8.5','8.7','8.8','8.9'],
      `A signal generator supplies a controlled test stimulus such as sine, square, pulse, sweep, audio/RF or function-generator output. Set waveform, amplitude, offset, frequency, source impedance and load assumptions before connection. A frequency counter measures event rate by counting cycles over a gate/timebase or related technique; accuracy is limited by timebase quality, gate time, trigger/signal level, noise and bandwidth. R-C-L substitution boxes provide known selectable resistance, capacitance or inductance so a technician can test whether circuit behavior changes when a suspected value is replaced under safe conditions; they are not a substitute for understanding voltage/current/power ratings. ESR meters estimate equivalent series resistance, particularly useful for finding degraded electrolytic capacitors whose capacitance may look plausible while internal loss is high. In-circuit readings can be influenced by parallel paths, so the measurement method and circuit state matter.`,
      'Choose between a function generator, frequency counter, RCL substitution box and ESR meter for four troubleshooting questions and name one limitation or setup requirement for each.',
      ['Explain generator stimulus settings','Explain counter timebase/gate/trigger/bandwidth limits','Explain controlled RCL substitution purpose','Explain ESR as loss/resistance indicator','Recognize in-circuit parallel-path/rating limitations']),
    S(8,3,'Logic probes and logic pulsers: observe versus stimulate',
      ['8.10','8.11'],
      `A logic probe is an observing instrument for digital nodes. Referenced to circuit ground and operated within its supported logic-family/voltage range, it indicates logic HIGH, LOW, and on many probes pulsing/activity. It does not tell you that a HIGH is “good” unless the expected logic state and threshold family are known. A logic pulser is the complementary stimulus tool: it injects a brief controlled logic transition or pulse at a node so the technician can see whether downstream logic responds. Used with a logic probe, oscilloscope or logic analyzer, it can separate “the upstream stage never changes” from “the downstream stage cannot respond.” Before pulsing, verify circuit supply/logic family, node direction, drive capability and that forcing the node will not create destructive bus contention or violate an analog/sensitive node. Example: if an AND-gate output is stuck, verify its supply and static inputs, safely pulse one eligible input while the other is at the enabling state, and observe the output. If the input changes but the output never follows, the gate/output path becomes a stronger suspect.`,
      'A digital node is stuck LOW. Explain how you would use a logic probe and, only if the node is safe to stimulate, a logic pulser to determine whether the failure is upstream or downstream.',
      ['Define logic probe as HIGH/LOW/pulse observation tool','Define logic pulser as controlled digital stimulus','Pair pulser with probe/scope/analyzer to observe downstream response','Verify logic family/supply/node direction before use','Avoid bus contention or pulsing unsuitable analog/sensitive nodes']),
    S(8,3,'Oscilloscope controls and spectrum analyzer operation',
      ['8.12','8.12.1','8.13'],
      `An oscilloscope displays voltage versus time. Vertical scale controls volts/division; vertical position establishes where the trace sits; coupling selects DC, AC or ground/reference behavior; probe factor must match the probe; horizontal time/division controls the visible time span; trigger source/level/slope/event stabilizes acquisition relative to a repeatable point; bandwidth/sample-rate/acquisition settings affect what can be trusted. Measure amplitude only after confirming probe factor and reference, and distinguish peak, peak-to-peak and RMS. A spectrum analyzer displays amplitude/power versus frequency. Center frequency and span choose the region, reference level and input attenuation protect/scale the input, and resolution bandwidth (RBW) trades frequency resolution against sweep/noise behavior; video bandwidth (VBW) smooths displayed noise. A spectrum analyzer answers “what frequencies are present,” while a scope answers “how does voltage change with time.” Neither input should be exposed to an unknown signal beyond its rated level.`,
      'For a 1 MHz square wave with suspected ringing and an unexpected RF spur, choose scope settings to inspect the time waveform and spectrum-analyzer settings to inspect the spur. Explain the purpose of trigger, RBW, and reference level.',
      ['Explain vertical/time/probe/coupling controls','Explain trigger source/level/slope purpose','Distinguish peak/Vpp/RMS','Explain center/span/reference/attenuation/RBW/VBW','Choose scope for time domain and spectrum analyzer for frequency domain']),
    S(8,3,'Dummy loads, rheostats, isolation transformers, Variacs, and potentiometers',
      ['8.14','8.15','8.16'],
      `A dummy load substitutes a known electrical load so equipment can be tested without the real antenna, speaker or system; it must match impedance and dissipate expected power. A rheostat is a two-terminal use of a variable resistor to adjust current/resistance and must be rated for the resulting power. A potentiometer is a three-terminal variable divider; the wiper samples a fraction of the voltage between the ends, subject to loading. An isolation transformer provides galvanic isolation between primary and secondary so the secondary is not directly bonded to the source conductor in the same way; it does not make contact with both secondary conductors safe and does not remove stored/high-energy hazards. A Variac (variable autotransformer) adjusts AC voltage with a movable tap but normally provides no galvanic isolation. Therefore “Variac = isolation” is false. Transformer/Variac size matters because VA/current/insulation ratings must exceed the test load and fault demands.`,
      'Compare a dummy load, rheostat, potentiometer, isolation transformer, and Variac. State the job each does and the dangerous misconception that a Variac automatically provides isolation.',
      ['Define dummy load and match impedance/power','Distinguish rheostat from potentiometer use','Explain potentiometer divider loading','Explain galvanic isolation and its limits','Explain Variac voltage adjustment without assumed isolation','Check VA/current/insulation/power ratings']),

    S(9,4,'Core formulas, SI prefixes, NIST spelling exceptions, and scientific notation',
      ['9.1','9.2','9.3','9.8','9.8.1','9.9'],
      `Technician math begins by writing the relationship with units. Core relationships include V=IR, P=VI, f=1/T, wavelength λ=v/f, XC=1/(2πfC), XL=2πfL and resonant frequency f0=1/(2π√LC), along with context-specific ratios such as transformer turns and dB. SI prefixes are powers of ten: p 10⁻¹², n 10⁻⁹, µ 10⁻⁶, m 10⁻³, k 10³, M 10⁶, G 10⁹. Prefix case matters: m is milli while M is mega. Scientific notation keeps the coefficient times 10^n and makes prefix conversion visible. NIST writing guidance includes traditional unit-name spellings such as kilohm and megohm as exceptions to simply joining a prefix name to “ohm”; symbols remain kΩ and MΩ. Correct calculations keep units through substitution and make an order-of-magnitude estimate before trusting a calculator.`,
      'Convert 4.7 kΩ, 220 µF, 3.3 MHz and 25 mA to base units/scientific notation, then compute the period of 3.3 MHz and explain the difference between m and M.',
      ['Use and rearrange core electronic formulas','Convert common SI prefixes with case sensitivity','Use scientific notation/exponents','Compute frequency/period/wavelength where data permits','Recognize kilohm/megohm spelling guidance and kΩ/MΩ symbols']),
    S(9,4,'Number systems and Boolean algebra',
      ['9.4','9.5'],
      `Digital systems represent values in binary (base 2), octal (base 8), decimal and hexadecimal (base 16). Each position has a weight equal to the base raised to the position number. Hex digits A-F represent decimal 10-15, and each hex digit maps directly to four binary bits; three binary bits map to one octal digit. Boolean algebra describes logic values and operations such as NOT, AND and OR. Identities such as A AND 1 = A, A OR 0 = A, A AND 0 = 0, and NOT(NOT A)=A help simplify logic. De Morgan’s laws connect inverted AND/OR forms: NOT(A AND B)=NOT A OR NOT B, and NOT(A OR B)=NOT A AND NOT B. Truth tables are the reliable check when symbolic simplification becomes confusing.`,
      'Convert 0x3A to binary and decimal, then simplify one Boolean expression and verify the result with a truth table.',
      ['Convert binary/decimal/octal/hex using place values/grouping','Use A-F hex values','Map hex nibble to four bits','Apply basic Boolean identities and NOT/AND/OR','Use a truth table to verify logic including De Morgan relationships']),
    S(9,4,'Decibels and graphs as engineering representations',
      ['9.6','9.7'],
      `Decibels express ratios logarithmically. For power ratios use 10 log10(P2/P1); for voltage ratios use 20 log10(V2/V1) only when the impedances are equal or the context justifies that conversion. +3 dB is about twice power, -3 dB about half power, +10 dB ten times power, and -10 dB one tenth. Absolute levels such as dBm add a reference; 0 dBm is 1 mW. Graphs reveal relationships that a single number hides: waveform plots show value versus time, frequency-response plots show gain/phase versus frequency, IV curves show device behavior, and trend plots show drift/repeatability. Always label axes, units, scale type (linear/log), reference and conditions; otherwise a graph can be technically true but misleading.`,
      'A stage drops from 10 mW to 5 mW. Calculate the dB power change, then sketch what information belongs on a frequency-response graph of the same stage.',
      ['Use 10log for power ratio','Use 20log voltage ratio only with proper impedance condition','Recognize approximate ±3/10 dB power relationships','Explain dBm reference concept','Label graph axes/units/scale/reference/conditions']),

    S(10,9,'Power-supply hazards, transformer versus line-connected supplies, and protection',
      ['10.1','10.2','10.6','10.8'],
      `Power supplies can contain hazardous mains voltage and stored capacitor energy even after the output appears low-voltage. A traditional transformer-isolated supply has galvanic separation between primary and secondary, but primary circuitry remains hazardous and the secondary may still store significant energy. Line-connected/non-isolated supplies reference parts of the circuitry directly to mains and require isolation-rated service methods. An integrated high-voltage transformer (IHVT, historically common in CRT/display high-voltage sections and often implemented as a flyback-style transformer assembly) combines the high-voltage transformer with associated rectification/multiplier or output functions in a compact module. It develops kilovolt-level output from switched/pulsed energy rather than simply passing line-frequency mains through an ordinary power transformer, and it can retain hazardous charge after power is removed. Treat the exact discharge, replacement, and servicing instructions for the product as authoritative. Overcurrent protection is normally placed so a fault is interrupted near the source before conductors/components overheat. Fuses/breakers are selected from equipment documentation and circuit requirements; house-service replacement is outside this course unless the person is qualified/authorized. Never “approximate” an unknown fuse upward. A replacement must match type, voltage, current and interrupting rating, and the underlying fault must be investigated.`,
      'Compare the service risk of an isolated transformer supply with a line-connected supply and explain where/why overcurrent protection is placed. State the replacement information required before changing a fuse.',
      ['Recognize stored/mains energy hazards','Differentiate galvanic-isolated and line-connected supplies','Recognize integrated high-voltage supply boundary','Explain source-side overcurrent protection purpose','Match fuse type/voltage/current/interrupting rating and do not up-rate']),
    S(10,9,'Batteries, charging, capacity, and protection',
      ['10.3','10.3.1'],
      `Battery chemistry determines nominal cell voltage, charge method, temperature behavior, energy density and failure hazards. Capacity in ampere-hours describes charge delivery under specified conditions, not an unlimited current source or exact run-time promise. Rechargeable cells require a chemistry-specific charger: lead-acid, NiMH and lithium-ion use different voltage/current/termination methods. Lithium-ion charging commonly uses controlled constant-current then constant-voltage phases with cell-voltage, temperature and current limits; a protection/BMS function may monitor overcharge, overdischarge, overcurrent and cell balance but does not make abuse safe. Primary/nonrechargeable cells must not be placed on a charger. Series cells raise voltage; parallel arrangements raise available capacity/current only when the design safely supports matched cells. Inspect swelling, damage, heat and polarity and follow manufacturer transport/disposal rules.`,
      'Explain why a generic bench supply set to “about the right voltage” is not automatically a safe battery charger, and describe the information you need before charging a lithium-ion pack.',
      ['Identify chemistry-specific charging requirement','Explain Ah as capacity under conditions','Explain common CC/CV lithium-ion concept','Recognize BMS/protection limits','Do not recharge primary cells; inspect damage/temperature/polarity']),
    S(10,9,'Rectification, L/T/Pi filters, regulation, and DC calculations',
      ['10.4','10.4.1','10.4.2','10.4.3','10.5','10.7','10.9','10.10'],
      `Rectifiers convert AC into unidirectional pulsating voltage. A half-wave circuit uses one polarity; a full-wave center-tapped or bridge rectifier uses both halves, increasing ripple frequency. A reservoir capacitor charges near waveform peaks and supplies load current between peaks, reducing hum/ripple. L-section filtering uses a series choke/inductor followed by a shunt capacitor; a T filter adds a second series choke after the capacitor; a Pi filter uses capacitor–inductor–capacitor so its schematic resembles π. These filters trade ripple reduction against size, loss, inrush and dynamic response. Regulation keeps output near target despite input/load changes using Zener, linear regulator, feedback/pass devices or switching methods. Multiple-output supplies can use separate windings/regulators or derived rails, each with its own current and reference limits. For sine-fed rectifiers, begin from the correct RMS-to-peak relationship (Vpk≈Vrms√2), then subtract appropriate diode drops and account for load/ripple rather than assuming the capacitor always sits at unloaded peak.`,
      'Sketch a bridge rectifier followed by Pi filtering and regulation. Explain the waveform at each stage and calculate an approximate no-load capacitor peak from a stated transformer RMS voltage.',
      ['Differentiate half-wave/full-wave/bridge rectification','Explain reservoir-capacitor ripple reduction','Identify L, T and Pi filter topology','Explain regulation purpose/components','Account for RMS-to-peak and diode drops','Recognize multiple-output rail/reference/current limits']),
    S(10,9,'Switch-mode power supply operation',
      ['10.11'],
      `A switch-mode power supply regulates energy by rapidly switching a semiconductor rather than continuously dissipating the full voltage difference in a pass device. The switch, inductor/transformer or other energy-storage element, diode or synchronous switch, output capacitor and feedback controller form a power-conversion loop. In a buck converter, the switching node alternates between source and ground-side states; the inductor/capacitor average that pulsed energy to a lower DC output. A boost converter rearranges energy transfer so output can exceed input. Flyback supplies store energy in a coupled magnetic element and can provide isolation. The controller changes duty cycle, frequency or pulse pattern according to feedback and protection limits. Technician symptoms include no switching, shorted switch, startup cycling, excessive ripple, wrong duty cycle, feedback/reference fault, overloaded/shorted output, dried capacitors and EMI/noise problems. Oscilloscope probing of primary-side switching nodes can be hazardous; use only rated/isolation procedures within training.`,
      'Trace energy through a buck SMPS from input switch to inductor/capacitor/load and explain how feedback changes duty cycle when output is low. Name three failure signatures and their likely block.',
      ['Explain high-frequency switching versus linear dissipation','Identify switch/energy-storage/rectification-filter/feedback blocks','Explain buck/boost/flyback roles at basic level','Connect feedback to duty/pulse control','Identify realistic startup/ripple/short/feedback/EMI fault signatures','Respect primary-side measurement safety'])
  ];

  const laterSections = [
    S(11,10,'Amplifier roles, classes, stages, and frequency response',
      ['11.1','11.3','11.4','11.5','11.9'],
      `An amplifier uses energy from its power supply to produce an output signal that is a controlled version of the input. A preamplifier raises a small sensor/microphone-level signal and often establishes noise/impedance performance; a line amplifier drives an interstage or line-level load; a power amplifier delivers substantial voltage/current to a load such as a speaker or actuator. Class A conducts for the full cycle and is linear but inefficient; Class B devices conduct for roughly half-cycles and can create crossover distortion; Class AB biases devices to overlap and reduce crossover distortion; Class D switches devices and filters the result for high efficiency. Frequency response describes gain versus frequency and therefore the usable bandwidth. A narrow-band amplifier intentionally favors a limited band, while broadband designs maintain useful gain over a much wider span and must control stability, noise and flatness. Gain figures only make sense with stated source/load conditions and frequency.`,
      'Compare a microphone preamp, line amplifier, Class AB power amp and Class D power amp. For each, name the signal/load role and one specification that would matter.',
      ['Differentiate preamp/line/power amplifier roles','Differentiate A/B/AB/D operating concepts','Explain frequency response and bandwidth','Compare broadband and narrow-band requirements','Tie gain/specifications to frequency and loading']),
    S(11,10,'BJT and FET amplifier bias, gain, and power',
      ['11.2','11.3.1','11.3.2'],
      `An amplifier stage needs a DC operating point (bias) so the signal can vary without immediately driving the device into cutoff or saturation/clipping. In a common-emitter BJT stage, the base/emitter network establishes current, the collector resistor converts collector-current changes to voltage changes, emitter resistance adds local feedback/stability, and coupling/bypass capacitors shape AC response. Small-signal voltage gain depends on device transconductance and surrounding resistances, while output swing is limited by supply and bias point. In a common-source FET/MOSFET stage, gate bias sets the operating region, drain current changes with gate-source voltage, and drain/source resistances set gain and feedback. For either type, first verify DC terminal voltages and current before calculating/observing AC gain. Power analysis distinguishes signal power from device dissipation: a transistor can meet gain target yet exceed safe dissipation.`,
      'Given DC terminal voltages for one BJT amplifier and one MOSFET amplifier, decide whether each device is plausibly biased in an amplifying region before estimating gain/power.',
      ['Identify purpose of bias/DC operating point','Explain common-emitter component roles','Explain common-source gate/drain/source roles','Verify DC state before AC gain','Distinguish signal gain/output power from device dissipation']),
    S(11,10,'Operational amplifiers and gain analysis',
      ['11.6','11.6.1'],
      `An operational amplifier is a high-gain differential amplifier normally used with feedback so external components define useful behavior. In the ideal negative-feedback model, input currents are approximately zero and feedback drives the two input voltages toward equality while the output remains inside its valid range. An inverting amplifier has gain Av = -Rf/Rin; a non-inverting amplifier has Av = 1 + Rf/Rg. Real op-amps have finite supply rails/output swing, input common-mode range, output-current limit, gain-bandwidth product, slew rate, offset and noise. A mathematically correct gain can therefore fail physically if the required output exceeds the rail, changes too quickly, or drives too heavy a load. Power checks include output/load power and device dissipation/thermal limit, not only gain. Comparator-like open-loop use is different from linear closed-loop operation.`,
      'Design an inverting op-amp stage for a stated gain, predict output for a sample input, then check whether that output is possible from the stated supply rails and load.',
      ['Use inverting and non-inverting gain equations','Explain virtual-equality/near-zero-input-current ideal rules under negative feedback','Check output rail/common-mode/current/bandwidth/slew limits','Distinguish linear feedback from comparator/open-loop use','Include load power/device dissipation checks']),
    S(11,10,'Distortion, loading, buffering, and measurement error',
      ['11.7','11.8','11.8.1'],
      `Distortion means the output is not a scaled/time-shifted version of the intended input. Clipping occurs when output swing reaches a limit; crossover distortion can appear near zero in poorly biased push-pull stages; slew-rate limiting distorts fast/large signals; overload, thermal/current limiting and nonlinear bias can add harmonics or compression. Measurement equipment can create apparent distortion or gain error by loading the circuit. A DMM or scope input has finite resistance and capacitance; a 1× scope probe often loads a high-impedance/high-frequency node more than a 10× probe. Reduce loading by selecting a higher-impedance probe/meter, using a 10× probe when appropriate, buffering the node, measuring at a lower-impedance test point, shortening grounds/leads, and accounting for bandwidth. A clean-looking waveform is not proof of the circuit’s unloaded behavior unless the instrument’s effect is considered.`,
      'A high-impedance amplifier node looks slower and lower in amplitude only when probed with a 1× scope probe. Explain the likely loading mechanism and give two valid measurement improvements.',
      ['Identify clipping/crossover/slew/overload distortion mechanisms','Explain finite meter/scope input loading','Explain 1× versus 10× probe tradeoff','Name buffering/high-impedance/short-ground/bandwidth remedies','Distinguish real circuit distortion from measurement-induced error']),

    S(12,18,'Signal levels, connectors, grounding, mismatch, and conflict symptoms',
      ['12.1','12.2','12.3','12.4'],
      `Interfaces fail when two devices disagree about voltage range, current drive, reference/ground, impedance, polarity, timing, connector pinout or signaling convention. Before connecting equipment, identify each side’s output type and allowable input range from documentation. A connector is not just a shape: keying, pin numbering, contact rating, shielding, retention and intended signal/power class matter. Grounds may be chassis, protective earth, analog reference, digital return or isolated secondary; tying them together blindly can create loops, shorts or unsafe paths, while failing to share a required signal reference can make a logic link unreadable. Power-source mismatch may present as no operation, overheating, reset, blown protection or damage. Signal-level conflict may produce clipping, constant logic HIGH/LOW, intermittent data, excessive noise, hum, distorted analog output, bus contention or damaged I/O. Level shifting, buffering, isolation, impedance matching or correct cabling solves specific incompatibilities; an adapter that only changes connector shape may solve none of them.`,
      'Before connecting two unknown devices, create an interface contract listing voltage, reference, direction, impedance/current, connector pins and timing. Then diagnose three symptoms caused by mismatches.',
      ['Identify expected signal levels/current/impedance/reference','Verify connector pinout/rating/keying rather than shape alone','Differentiate protective earth/chassis/signal reference concepts at technician level','Recognize mismatch/conflict symptoms','Choose level shifting/buffering/isolation/matching based on actual mismatch']),
    S(12,18,'USB, I2C, and Zigbee interfaces',
      ['12.5'],
      `USB, I2C and Zigbee solve very different interface problems. USB is a host/device serial bus with differential data signaling, defined connectors/power roles and enumeration: a device must be electrically connected and then recognized/configured by the host protocol stack. I2C is a short-distance board-level two-wire bus using SDA and SCL with open-drain/open-collector style drivers and pull-up resistors; devices use addresses and acknowledge (ACK/NACK) transfers. The bus can fail from wrong address, missing/incorrect pull-ups, voltage-level mismatch, stuck-low device, timing or wiring faults. Zigbee is a low-power wireless networking technology built on IEEE 802.15.4 radios and adds network/application behavior beyond a simple point-to-point wire. It introduces channel/interference, joining/addressing/network topology and RF-range considerations. “Serial interface” is therefore not enough detail: physical/electrical layer and protocol behavior must both be identified.`,
      'Compare the bring-up evidence for a USB device, an I2C sensor and a Zigbee node. What proves electrical connection, and what additional protocol/network evidence is needed?',
      ['Explain USB host/device, differential connection and enumeration concept','Explain I2C SDA/SCL/open-drain/pull-up/address/ACK behavior','Identify common I2C electrical/protocol failures','Explain Zigbee as IEEE 802.15.4-based low-power wireless network','Distinguish physical/electrical connection from protocol success']),

    S(13,11,'Logic gates, truth tables, and flip-flops',
      ['13.1','13.2','13.4'],
      `Digital gates implement Boolean relationships: NOT inverts, AND requires all asserted inputs, OR requires any asserted input, NAND/NOR invert AND/OR, XOR asserts for unequal/odd-parity inputs, and XNOR asserts for equality/even parity. A truth table enumerates every input combination and expected output; for n binary inputs it has 2^n rows. Flip-flops store state rather than responding only to current inputs. An SR latch/flip-flop represents set/reset behavior; D flip-flops capture a data state on a specified clock edge; JK/T types provide related toggle/control behavior. Setup and hold requirements mean data must be stable around the active clock edge. When troubleshooting, distinguish combinational logic (output from present inputs) from sequential logic (output also depends on stored state/clock history).`,
      'Construct the truth table for a two-input XOR and NAND, then explain how a D flip-flop behaves differently from either gate when the input changes between clock edges.',
      ['Identify common gate symbols/functions','Construct full truth tables','Differentiate combinational and sequential logic','Explain D/SR/JK/T roles at introductory level','Recognize clock-edge and setup/hold concept']),
    S(13,11,'Counters, buses, clocks, timing, and logic families',
      ['13.3','13.5','13.10','13.11'],
      `A counter advances through a defined state sequence in response to clock events; ripple counters propagate changes stage-to-stage, while synchronous counters update stages from a common clock. A bus is a shared set of conductors/signals carrying data, address or control information among functional blocks; bus direction, width, enable/tri-state behavior and timing must be understood before probing. Digital clocks establish event timing. Frequency and period describe rate, while propagation delay, rise/fall time, jitter, skew, setup and hold describe whether data is valid when sampled. Logic families such as TTL and CMOS have defined supply ranges and HIGH/LOW input/output thresholds; a voltage between guaranteed LOW and HIGH regions is not a valid state. CMOS inputs must not float, and 5 V TTL/CMOS outputs are not automatically safe for 3.3 V MCU inputs.`,
      'A 3.3 V MCU samples an 8-bit bus on a clock edge. Explain what must be true about thresholds, bus enable, setup/hold and skew for the sample to be valid.',
      ['Explain counter state progression and ripple vs synchronous concept','Define data/address/control bus and width/direction','Explain clock period/frequency and propagation/jitter/skew/setup/hold','Use logic-family thresholds rather than “any nonzero voltage = 1”','Recognize floating-input and voltage-compatibility problems']),
    S(13,11,'Digital displays and microcontrollers',
      ['13.6','13.12'],
      `Digital display circuitry translates binary/encoded data into visible segments, pixels or characters. A seven-segment display uses individually driven LED segments; common-anode and common-cathode packages require opposite drive polarity, and multiplexing rapidly selects digits while sharing segment lines. Character/LCD/OLED modules may include their own controller and interface, so the technician separates “data sent correctly” from “display power/contrast/backlight/pixel drive works.” A microcontroller integrates a processor core with memory and peripherals such as GPIO, timers, ADC, serial interfaces and debug logic. Simple firmware reads inputs, transforms state and writes outputs using variables, conditions, loops, functions and hardware-register/driver calls. An MCU is not merely a small PC: timing, pin electrical limits, reset/clock configuration and direct hardware state are part of correct programming.`,
      'Explain how a two-digit multiplexed seven-segment display is driven and why common-anode/common-cathode matters. Then describe the minimum MCU blocks needed to read a button and update the display.',
      ['Explain seven-segment segment/digit drive','Differentiate common-anode/common-cathode polarity','Explain multiplexing','Identify MCU core/memory/GPIO/timer/peripheral/debug blocks','Connect simple program control flow to physical I/O']),
    S(13,11,'Logic pulser/probe digital signal tracing and fault isolation',
      ['13.7','13.8','13.9'],
      `Digital signal tracing follows expected logic states and transitions through a known path. A logic probe observes HIGH, LOW and often pulse/activity; a logic pulser can provide a controlled transition to a safe node. First verify power, ground/reference and logic-family thresholds. Then choose a known stimulus and predict the state at each boundary. If an upstream node never changes, the fault may be before that point; if a safe forced pulse reaches an input but no expected downstream transition appears, the downstream gate/enable/output path becomes suspect. Oscilloscopes or logic analyzers are preferred when pulse width/timing/order matters. Do not pulse bidirectional buses, analog nodes or outputs actively driven against the pulser without confirming the tool/circuit permits it. The objective is to isolate the first incorrect logic relationship, not simply to find a pin that “looks dead.”`,
      'Trace a digital fault through three gates using expected truth-table states. Show where a logic probe is sufficient and where a pulser/scope/logic analyzer adds discriminating evidence.',
      ['Use known input and expected states','Use probe for HIGH/LOW/activity','Use pulser only on safe eligible node','Escalate to scope/analyzer for timing/pulse/order questions','Locate first violated logic relationship and avoid contention']),

    S(15,14,'Computer architecture, CPU blocks, memory, block diagrams, and flowcharts',
      ['15.1','15.2','15.3','15.4'],
      `A computer system can be divided into input, processing, memory/storage, communication and output. Inside a processor/microprocessor, the control unit sequences operations, the arithmetic/logic unit performs calculations/logic, registers hold immediate working state, buses/interconnect move addresses/data/control, and clock/reset mechanisms coordinate startup/execution. Cache and memory interfaces reduce the speed gap to external memory. Volatile RAM loses contents without power; nonvolatile flash/ROM retains code/data; mass storage provides longer-term file storage with very different latency/endurance. A computer block diagram shows hardware/data relationships, while a software flowchart shows sequence and decisions. Troubleshooting uses both: “which block should receive this signal/data?” is a block-diagram question; “which branch should execute next?” is a flowchart question.`,
      'Draw a minimal computer block diagram and trace what happens from power/reset through instruction fetch to an output. Then distinguish RAM, flash/ROM and mass storage.',
      ['Identify input/processing/memory/storage/communication/output sections','Name control unit/ALU/register/bus/clock-reset roles','Differentiate volatile and nonvolatile memory/storage','Use block diagram for architecture and flowchart for sequence','Trace instruction/data movement at introductory level']),
    S(15,14,'PLC purpose, scan cycle, programming concepts, and languages',
      ['15.5','15.6','15.7'],
      `A programmable logic controller is an industrial controller designed for deterministic I/O control and rugged environments. A basic PLC scan reads inputs, executes the control program, updates outputs and performs communications/diagnostics; exact behavior depends on platform. Ladder logic represents relay-like contacts/coils and is common in industrial work, while function-block, structured-text and other IEC-style languages express the same control intent in different forms. Programming concepts still include variables/tags, Boolean conditions, timers, counters, state, functions, sequence and error handling. Different languages exist because some make discrete control, math/data handling, state machines or reusable algorithms easier to express and maintain. A technician must distinguish a physical input state from a software tag and an output command from actual field voltage/current; forcing a software bit does not prove the field circuit is healthy.`,
      'Explain a PLC scan and write the same simple start/stop motor-control intent in plain-language ladder terms and structured pseudocode, then identify what field evidence is still required.',
      ['Define PLC use and rugged I/O-control role','Describe input-execute-output scan cycle','Identify ladder/function-block/structured-text type differences','Use variables/timers/counters/state concepts','Distinguish software state from physical I/O evidence']),
    S(15,14,'Peripherals and interface devices/cards',
      ['15.8','15.9'],
      `A peripheral is an attached device that extends input, output, storage, sensing or communication capability: keyboards, displays, printers, drives, cameras, USB devices and network adapters are examples. Interface devices/chips/cards bridge electrical/protocol expectations between the CPU/system bus and external equipment. Examples include USB controllers/hubs, UART/serial interfaces, Ethernet/network interface controllers, storage controllers, audio codecs/interfaces, GPIO/I/O expanders and data-acquisition cards. Installing hardware is only part of bring-up: power, connector/pinout, bus enumeration, driver, address/resource configuration and functional test must all agree. An unrecognized peripheral may be a cable/power/port problem, missing driver, unsupported protocol/device class, resource/configuration issue or failed hardware.`,
      'A newly installed USB data-acquisition peripheral is powered but not detected. Build a fault-isolation sequence that separates physical connection, enumeration, driver/configuration and hardware failure.',
      ['Define peripheral with examples','Name common interface chip/card categories','Separate power/physical/bus/driver/configuration layers','Use enumeration/resource evidence','Avoid assuming “powered = communicating”']),

    S(16,17,'Basic operation, setup/configuration, and stand-alone versus networked computers',
      ['16.1','16.2','16.3','16.10'],
      `A computer boots through firmware/bootloader stages into an operating system that manages CPU time, memory, files, devices and applications. Setup begins with verified hardware/power, firmware settings where necessary, storage/OS installation, device drivers, user/security configuration, updates and functional tests. Configuration means selecting settings appropriate to hardware and use—display/network/ports, storage, permissions, services, time, power and application options—not randomly changing defaults. Drivers translate OS requests into device-specific operations. A stand-alone computer can operate without network services; a networked computer additionally depends on interface configuration, link, IP addressing, local switching/routing, DNS/name resolution and remote services. Troubleshooting therefore identifies which layer fails instead of reinstalling everything.`,
      'A workstation boots and local files work but it cannot reach a named network service. Separate basic computer operation from link/IP/router/DNS/service checks and state what evidence belongs at each layer.',
      ['Explain boot/OS/driver/application relationship','Outline setup and configuration stages','Explain why configuration choices are purpose-specific','Differentiate stand-alone from network dependencies','Use layered network troubleshooting rather than indiscriminate reinstall']),
    S(16,17,'Program installation, utilities, backups, downloads, and recovery',
      ['16.4','16.5','16.6','16.9'],
      `Programs should be obtained from trusted sources, checked for supported OS/hardware/version, installed with the least privilege necessary, and recorded so the configuration can be reproduced. Utilities include file/disk tools, task/process monitors, logs/event viewers, compression/archive tools, diagnostics, update tools and security scanners; each answers a specific maintenance question. Backup means keeping recoverable copies separate from the working data. Useful strategies combine versions and, where appropriate, local plus offline/off-site/cloud copies; synchronization alone is not a backup because deletion/corruption can synchronize too. Recovery is not proven until a restore is tested. Downloads should be verified by source, filename/version, digital signature or checksum when provided, and scanned/handled according to security policy. Store installers/configuration notes where licensing and policy allow so a system can be rebuilt.`,
      'Create a safe installation-and-backup plan for a technician tool, including source verification, version/requirements, rollback, backup, restore test and evidence.',
      ['Use trusted/download-verification practices','Identify utility software purposes','Distinguish backup from sync','Require restore testing','Record version/configuration/rollback evidence']),
    S(16,17,'Surges versus malware and practical cybersecurity/network use',
      ['16.7','16.8'],
      `A line surge is an electrical overvoltage/transient problem; malware/virus infection is a software/security problem. Surge protection uses properly selected protective devices, grounding/bonding and system design, while malware protection uses patching, least privilege, reputable endpoint protection, application/source control and backups. One does not protect against the other. Internet access requires a functioning network interface/link and an IP path through switches/routers; DNS translates names to addresses, while application protocols/services operate above that. Cybersecurity basics include unique strong credentials with MFA where available, updates, phishing awareness, least privilege, trusted software sources, protected secrets, secure Wi-Fi/VPN practices as required, backups and prompt reporting of suspected compromise. A technician should preserve logs/evidence and follow organization incident procedures rather than experimenting on a suspected compromised production system.`,
      'A PC resets during storms and also shows browser redirects after an unknown download. Explain why these are different fault classes and give separate electrical and cybersecurity response paths.',
      ['Differentiate surge/transient from malware','Name electrical surge-protection controls','Name patching/least-privilege/MFA/source-control/security controls','Explain link/IP/router/DNS/application layers','Preserve/report evidence on suspected compromise']),

    S(17,19,'Audio/video blocks, microphones, speakers, recording and playback',
      ['17.1','17.2','17.3','17.4'],
      `A typical audio/video chain has source/transducer, conditioning/preamp, conversion or processing, transport/storage, power/driver stage and output/display/transducer. A dynamic microphone generates voltage from coil/magnet motion and usually needs no polarization power; a condenser microphone uses a capacitive element and active electronics and commonly requires bias/phantom power depending on type. A loudspeaker converts electrical current in a voice coil and magnetic field into motion; impedance, power, enclosure and thermal/mechanical limits matter. Recording converts the source signal into a stored representation—analog magnetic/physical or, commonly, sampled/quantized digital data through an ADC/codec. Playback reverses the path through decoding/DAC/amplification to the transducer. The technician follows signal level and format at each boundary rather than treating “audio” or “video” as one homogeneous signal.`,
      'Trace speech from a microphone through digital recording and back to a speaker, identifying transduction, conversion, storage/processing and power-amplification boundaries.',
      ['Identify major entertainment/audio-video blocks','Differentiate dynamic and condenser microphone concepts','Explain speaker electromechanical conversion and ratings','Explain ADC/DAC/codec role in digital recording/playback','Trace signal format/level boundary by boundary']),
    S(17,19,'Interfacing, distortion, conflicts, fault isolation, and signal levels',
      ['17.5','17.6','17.7','17.8','17.9'],
      `Interfacing alarm/security, entertainment and information products requires compatible signal type, level, reference, impedance and connector/protocol. Audio levels are relative categories rather than one exact voltage: microphone level is small, line level is larger but intended for high-impedance line inputs, headphone outputs can drive moderate loads, and speaker outputs deliver far greater current/power to low-impedance loads. Connecting a speaker-level output to a microphone input can clip or damage the input. Distortion can come from clipping/overload, crossover/nonlinearity, bad source material, speaker excursion/thermal limit, grounding/hum, bandwidth limitation or sampling/codec artifacts. To isolate a glitch between discrete units, substitute a known-good source/load/cable or observe the signal at the interface while changing one element. Ground loops may create hum; incompatible formats or levels may create silence, clipping, noise or intermittent behavior.`,
      'A receiver output is distorted only when connected to one external amplifier. Give a boundary-isolation plan that distinguishes source distortion, cable/ground problem, level mismatch and amplifier fault.',
      ['Distinguish mic/line/headphone/speaker level categories','Recognize overload/impedance/ground/format conflict symptoms','Identify common distortion mechanisms','Use known-good substitution/interface measurement','Explain alarm/security interface still requires electrical/protocol compatibility']),

    S(18,19,'Display technologies: LED, seven-segment, LCD, OLED, and tradeoffs',
      ['18.1','18.1.1','18.2','18.2.1','18.2.2'],
      `Electronic displays convert electrical drive into controlled visible output. An LED emits light when forward-biased; current must be limited and polarity observed. A seven-segment display groups LEDs into segments that form numerals. Common-anode packages share positive supply and light a segment by pulling its cathode low; common-cathode packages share return and light a segment by driving its anode high. Multiplexed displays rapidly select digits to reduce wiring/driver count. An LCD is not normally self-emissive: an electric field changes liquid-crystal optical behavior, with a backlight often providing illumination; DC bias must be controlled according to the driver because sustained DC can damage/age segments. OLED pixels are emissive organic devices, providing high contrast and no backlight but with current/aging/burn-in considerations. Display choice balances brightness, power, contrast, viewing angle, lifetime, drive complexity, cost and environment.`,
      'Compare a discrete LED, common-anode seven-segment display, LCD and OLED by drive method, whether the technology emits its own light, and one practical advantage/disadvantage.',
      ['Explain LED forward/current-limited operation','Explain seven-segment common-anode/cathode and multiplexing','Explain LCD light-modulation/backlight concept','Explain OLED emissive-pixel concept','Compare power/contrast/aging/drive tradeoffs']),
    S(18,19,'Photovoltaic cells, photodiodes, phototransistors, LDRs, materials, and symbols',
      ['18.3','18.3.1','18.3.2','18.6','18.6.1'],
      `Photoelectronic devices convert light and electrical behavior in different ways. A photovoltaic cell generates voltage/current when photons create charge carriers in a semiconductor junction; greater illumination generally increases available photocurrent, while voltage/current depend on cell and load. Photodiodes produce light-dependent current and are often operated reverse-biased for speed/linearity or in photovoltaic mode for sensing. Phototransistors use light-generated base action to provide current gain and greater sensitivity with slower response. A photoresistor/LDR changes resistance with light level and is slower/nonlinear but simple for threshold controls. Common materials include silicon for many visible/near-IR devices and compound semiconductors such as GaAs/GaN families for other spectral/emission needs; exact spectral response comes from the datasheet. Schematic symbols distinguish resistor-with-light-arrows, diode-with-light-arrows and transistor-with-light-arrows. Light-activated controls convert sensor output into a threshold/analog/digital decision that then drives a relay, transistor, MCU input or other stage.`,
      'Given three light sensors—LDR, photodiode and phototransistor—choose one for a fast optical data detector, one for a simple day/night switch and one for higher-gain light detection, and justify the choice.',
      ['Explain photovoltaic activation and load-dependent output','Differentiate photodiode/phototransistor/LDR mechanisms','Identify representative semiconductor-material concept without overgeneralizing','Recognize schematic symbols via light arrows/device symbol','Connect sensor output to light-activated control circuitry']),
    S(18,19,'Cameras, opto-isolators, and broadband optical links',
      ['18.4','18.5','18.5.1','18.7'],
      `Electronic cameras focus light onto an image sensor array (commonly CMOS), where pixels convert photons into charge/electrical signals that are read, amplified and converted to digital image data. Exposure depends on light, lens/aperture, integration time/shutter and sensor gain. An opto-isolator/opto-coupler contains a light emitter, usually an LED, and an isolated detector such as a phototransistor/photodiode. The light path transfers information while maintaining galvanic isolation between input and output circuits within the device ratings. Uses include isolating low-voltage control from higher-voltage power stages, breaking ground paths, isolated feedback and digital input/output. Isolation voltage, creepage/clearance, transfer ratio, speed and aging matter; an optocoupler is not an unlimited safety barrier. Broadband optical links encode/modulate information onto light through fiber; RF broadband links use electromagnetic carriers/antennas. Both have transmitter, medium/channel, receiver, bandwidth, attenuation/noise and link-budget concerns, but the physical medium and hazards differ.`,
      'Trace a camera pixel-to-digital-image path, then explain how an opto-isolator can pass a logic/control signal without a conductive signal path. Give two real circuit locations for opto-isolation.',
      ['Explain lens/sensor/readout/ADC digital image chain','Explain optocoupler emitter-detector galvanic isolation','Name control/power/feedback/I-O isolation applications','Check isolation/speed/transfer/creepage ratings','Compare optical-fiber and RF broadband link blocks']),

    S(19,20,'Wave propagation, fields, polarization, and wavelength',
      ['19.1','19.3','19.10'],
      `Radio communication uses time-varying electromagnetic fields that propagate energy away from an antenna. The electric (E) and magnetic (H) fields are linked components of the propagating wave; electrostatic fields are associated with essentially static charge and do not by themselves describe a radiated RF wave. Polarization describes the orientation/time behavior of the wave’s electric field (for example horizontal, vertical or circular) and should match the receiving antenna for efficient coupling. In free space, wavelength and frequency satisfy λ = c/f, where c is approximately 3×10^8 m/s. Higher frequency therefore has shorter wavelength. Propagation is affected by free-space loss, reflection, diffraction, absorption, multipath and the environment. A technician uses frequency/wavelength to recognize antenna scale and cable/fixture behavior but follows approved RF-exposure boundaries rather than experimenting with transmit power.`,
      'Calculate the approximate free-space wavelength at 100 MHz and 2.4 GHz, then explain why antenna polarization mismatch and multipath can reduce a received signal.',
      ['Explain propagating E/H field concept','Distinguish electrostatic field from radiated RF context','Define polarization','Use λ=c/f','Name reflection/diffraction/absorption/multipath effects']),
    S(19,20,'Antennas, feedlines, impedance matching, SWR/VSWR, and feedline types',
      ['19.2','19.2.1','19.9','19.11'],
      `An antenna converts guided RF energy on a feedline into radiated electromagnetic energy and performs the reciprocal receive function. Feedline types include coaxial cable (unbalanced, shielded, common at 50 Ω or 75 Ω), balanced twin-lead/ladder line (two spaced conductors with characteristic impedance set by geometry/dielectric), waveguide (a hollow/structured guide used especially at microwave frequencies above cutoff), and PCB transmission lines such as microstrip/stripline between RF circuitry and connectors/antennas. Feedlines have characteristic impedance determined by geometry/material, not ordinary DC resistance. When load/antenna impedance does not match the feedline/source, part of the wave reflects. Standing-wave ratio expresses mismatch; VSWR = (1+|Γ|)/(1-|Γ|), with 1:1 ideal. Causes include wrong cable/connector impedance, antenna detuning, damaged/wet cable, poor termination and frequency change. A dummy load matched to the system lets a technician separate transmitter/feedline/antenna problems without radiating through the antenna.`,
      'List and distinguish coax, twin-lead/ladder line, waveguide and microstrip/stripline. Then explain how an impedance mismatch creates reflections/VSWR and how a dummy load helps isolate the fault.',
      ['List actual feedline/transmission-line types','Explain characteristic impedance is geometry/material property, not DC resistance','Explain antenna guided-to-radiated conversion','Explain mismatch/reflection/SWR/VSWR concept','Name common mismatch causes and dummy-load diagnostic role']),
    S(19,20,'Modulation, communications receivers, and radio usage',
      ['19.4','19.5','19.6'],
      `Modulation changes a carrier or symbol stream to represent information. AM changes carrier amplitude; FM changes instantaneous frequency. Digital radio systems use symbol modulation/coding such as PSK/QAM families and multiple-access/network methods. CDMA is a code-division access technique, while GSM, LTE and 5G are generations/standards that combine modulation, coding and multiple-access methods—do not treat all four as interchangeable “modulations.” Communications radios are designed for two-way or service-specific transmit/receive operation, while commercial broadcast receivers are primarily one-way receivers. A generic receiver path is antenna/preselector → low-noise/RF amplifier → mixer/local oscillator (or direct-sampling equivalent) → IF/baseband filtering/amplification → demodulation/decoding → audio/data output. Automatic gain/control and synthesizers may support the chain. Troubleshooting follows signal level/frequency through these stages.`,
      'Compare AM, FM and a digital QAM/PSK-style signal at a conceptual level, then draw a superheterodyne-style receiver chain and identify where tuning and demodulation occur.',
      ['Differentiate amplitude/frequency/digital modulation concepts','Avoid mislabeling CDMA/GSM/LTE/5G as identical modulation types','Differentiate two-way communications radio and broadcast receiver use','Identify receiver RF/mixer-LO/IF/baseband/demod-output blocks','Use block-level signal tracing']),
    S(19,20,'Spectrum bands and radio tuning/alignment',
      ['19.7','19.8'],
      `Frequency bands group services and equipment by spectrum region—for example HF, VHF, UHF and microwave ranges, with exact allocations controlled by regulators and service rules. A technician should recognize the names/order and use current allocation tables rather than memorize every service edge indefinitely. Tuning means adjusting or electronically selecting a resonant/synthesized path so the desired signal/channel is passed or generated. Older circuits may use variable capacitors/inductors and IF alignment; modern radios commonly use PLL synthesizers, digitally controlled filters and software calibration. Alignment is not random “tweaking”: establish the correct test signal, instrument/reference, order of adjustments and target from service documentation. Misalignment can reduce sensitivity, selectivity, power or spectral compliance.`,
      'Put HF, VHF, UHF and microwave in increasing frequency order and explain the difference between tuning a PLL-synthesized receiver and blindly adjusting an RF coil.',
      ['Recognize common spectrum band names/order','Use current allocation/service documentation for exact bands','Explain resonant/synthesized tuning concept','Explain PLL-based modern tuning role','Require service procedure/test signal/target before alignment']),

    S(20,20,'Two-way, cellular/wireless, and satellite communications',
      ['20.1','20.2','20.3'],
      `Two-way radio systems include land-mobile, public-safety, maritime, aviation and other services, each with assigned channels, operating practices and regulatory requirements. A wireless telephone/data system connects a user device through a radio access network/base station to switching/routing/core networks and onward services. Modern cellular standards use cells, mobility management, channel/resource scheduling, authentication and packet data. Applicable standards depend on the system: ANSI/TIA-603 covers measurement/performance for certain land-mobile FM/PM equipment, the TIA-102 family covers Project 25 land-mobile digital radio, and cellular generations are primarily specified through 3GPP plus carrier/vendor requirements. The technician should identify the standard named for the actual product/service instead of assuming one document covers every wireless system. Satellite communication adds an uplink from earth to satellite, a transponder/payload that receives/translates/amplifies/routes, and a downlink to another earth terminal. Link performance depends on path loss, antenna gain, frequency, atmospheric effects, noise and alignment; satellite distance also creates noticeable propagation delay. Service category determines allowed frequency/power and installation practice.`,
      'Compare a land-mobile two-way radio call, a cellular data session and a satellite link by tracing the path and identifying the network/infrastructure each depends on.',
      ['Identify major two-way service categories','Explain mobile device-base/core network concept','Recognize standards references can change by generation/application','Explain satellite uplink-transponder-downlink path','Recognize path loss/gain/alignment/delay considerations']),
    S(20,20,'Wired data/voice networks and POTS',
      ['20.4','20.5'],
      `Wired data networks commonly use Ethernet over twisted pair/fiber: endpoints connect through switches at the local-link layer, while routers move IP packets between networks. Link indication does not prove IP, DNS or application success, and a continuity pass does not prove category/bandwidth performance. Traditional POTS (plain old telephone service) uses a two-wire tip/ring loop carrying DC loop current for off-hook signaling plus superimposed voice AC and higher-voltage ringing from the central-office/adapter side. Polarity conventions and exact voltages vary by system and country, so service documentation controls. Splices/terminations must preserve pair continuity and insulation and avoid shorts/grounds/crossed pairs. Troubleshooting separates physical pair fault, loop/ringing condition and network/service-side problem; do not treat telecom pairs as harmless simply because they are “low voltage,” because ringing/transients may be present.`,
      'Explain the difference among Ethernet link, IP reachability and application/DNS success, then describe a basic POTS tip/ring loop including off-hook loop current and ringing.',
      ['Explain switch versus router roles','Separate physical link from IP/DNS/application layers','Describe POTS two-wire tip/ring loop concept','Explain off-hook loop current and ringing at a basic level','Recognize splice/cross/short/ground and ringing safety considerations']),

    S(21,28,'Service business records, invoices, productivity, and estimates/test planning',
      ['21.1','21.4','21.5','21.7'],
      `Technical service work must be economically and technically traceable. An invoice typically identifies customer/work order, labor/time, parts/material, rates, taxes/fees where applicable, and the authorized work performed; it should not hide technical uncertainty behind vague descriptions. Service records preserve asset/serial/revision, complaint, test conditions, measurements, diagnosis, parts/actions, retest and disposition. Productivity can be expressed as useful completed/accepted work relative to available labor hours or another organization-defined measure, but speed alone is not quality: rework, safety and first-pass yield matter. An estimate states scope, assumptions, labor, parts, test/verification time, risk/contingency and exclusions. Test planning belongs in the estimate because diagnosis and verification consume real time/equipment. If new evidence changes scope, document and obtain the required authorization rather than silently expanding work.`,
      'Build a mini service estimate and closeout record for an intermittent board fault, including labor/test time, parts assumption, evidence, authorization boundary and a defensible productivity measure.',
      ['Identify invoice/work-order elements','Record technical complaint-test-diagnosis-action-retest trace','Calculate productivity with defined numerator/denominator','Include diagnostic/verification time in estimate','State assumptions/exclusions/change authorization']),
    S(21,28,'Service literature, parts cross-reference, and manufacturer support',
      ['21.2','21.3','21.6'],
      `Service literature comes from manufacturer service manuals, schematics, datasheets, technical bulletins, parts catalogs, distributor/manufacturer portals and controlled internal documentation. Match exact model, serial range, board revision and document revision before applying instructions. Parts cross-reference is an engineering comparison, not a name match: verify function, package/pinout, voltage/current/power, tolerance, frequency/speed, temperature, safety/listing and lifecycle constraints. When documentation is ambiguous, a manufacturer help desk/service department can confirm compatibility, known issues, firmware, service procedure or part supersession. Contact support with precise evidence: model/serial/revision, symptom, test conditions, measurements, steps already taken, firmware/software versions and a focused question. Record the case number/advice and verify the result; do not treat an informal answer as permission to violate safety or regulatory requirements.`,
      'A legacy part is obsolete and a distributor lists a “replacement.” Describe the cross-reference checks and the exact evidence/question you would send to manufacturer support before approving substitution.',
      ['Use authoritative model/revision-matched literature','Compare pinout/package/electrical/timing/environment/listing constraints','Recognize distributor cross-reference as candidate, not proof','Provide precise symptom/test/version evidence to support','Record case/advice and verify result']),
    S(21,28,'Field versus shop procedure and project management',
      ['21.8','21.9'],
      `Field work adds travel, site access, customer operations, environmental hazards, limited bench equipment, change control and communication constraints that may not exist in a shop. A field technician confirms scope/contact, site safety/authorization, tools/spares, drawings/configuration, backup/rollback, outage window and test plan before changing equipment. Protect the customer’s operational state and record before/after configuration. Project management converts a larger objective into scope, requirements, tasks, dependencies, resources, schedule, risks, communication, verification and closeout. Track blockers and changes rather than hiding them. A technical project is complete when acceptance criteria are demonstrated, unresolved items are dispositioned, documentation/evidence is handed off, and the system is left in an agreed safe state—not when the technician merely runs out of time.`,
      'Create a field-service project plan for replacing and validating a controller at a customer site, including pre-arrival preparation, outage/rollback, verification, communication and closeout.',
      ['Differentiate field constraints from shop routine','Confirm site authorization/safety/access/tools/spares','Include backup/rollback/outage window/test plan','Define project scope/tasks/dependencies/risks/communication','Close with acceptance evidence, unresolved-item disposition and safe handoff'])
  ];

  const careerSections = [
    S('C1',1,'Career integration: bench safety, ESD, pre-power control, and hazard logging',
      ['C1.1','C1.2','C1.3','C1.4','C1.5','C1.6'],
      `A technician-controlled bench begins before energizing: identify source voltage/current capability, set a conservative current limit, verify polarity and connector orientation, inspect for shorts/exposed conductors, select the correct DMM mode/jack, establish an explicit stop condition, and document the setup. ESD controls protect semiconductors but do not substitute for shock/energy controls. Soldering/rework adds eye protection, ventilation, hot-tool and cutting/crimp hazards. The decision boundary is part of competence: isolated current-limited low-voltage work can be appropriate for this course, while unknown energized equipment, mains, high-energy batteries or charged high-voltage capacitors require trained/qualified procedures. C1.6 is explicit: if a safety/setup hazard is discovered, stop the test, record the condition and risk, correct it, independently verify the safe state/settings, record the corrective action, and only then continue under the required authorization.`,
      'Create a pre-power/hazard log for a low-voltage board where you discover reversed supply polarity before energizing. Show the stop, correction, independent verification, and authorization/continue decision.',
      ['Current limit and pre-power inspection','ESD and task-appropriate PPE/ventilation','Low-voltage versus qualified-work boundary','Explicit stop condition','C1.6 hazard-condition/risk/corrective-action/verification record']),
    S('C2',13,'Career integration: schematics, datasheets, design intent, and test-point prediction',
      ['C2.1','C2.2','C2.3','C2.4','C2.5','C2.6'],
      `Professional schematic reading is prediction before probing. Start at power/ground and connectors, follow reference designators and signal direction, identify functional blocks, then use the exact component datasheet to confirm pinout, absolute maximum ratings, recommended operating conditions and electrical characteristics. Absolute maximum is a damage boundary, not a normal design target. Choose the drawing type for the question: schematic for electrical function, wiring/harness for physical connection, block diagram for stages, PCB/layout for physical location/routing, timing diagram for time relationships. Support parts such as pull-ups/pull-downs, decoupling capacitors, series/current-limiting resistors and clamps often reveal design intent. Mark expected node voltages/waveforms and useful test points before touching an instrument; those predictions become the troubleshooting acceptance criteria.`,
      'Given a regulator-plus-MCU schematic and two datasheet excerpts, mark the power/signal path, safe test points, expected node values, and the support components that reveal design intent.',
      ['Trace power/ground/signal/reference designators','Use datasheet pinout/max/recommended/electrical specs correctly','Choose schematic/wiring/block/layout/timing representation','Identify useful test points before probing','Interpret pull/decoupling/limiting/protection support circuitry','Predict expected node behavior']),
    S('C3',3,'Career integration: hypothesis-driven measurement and instruments',
      ['C3.1','C3.2','C3.3','C3.4','C3.5','C3.6'],
      `Instrument choice follows the hypothesis. Use a DMM for static voltage/resistance/current with correct mode/jack/connection; use a current-limited bench supply to expose abnormal consumption during bring-up; use a scope when waveform shape, amplitude, offset, rise/fall, frequency or timing matters; use a logic analyzer when multiple digital channels/protocol transactions must be correlated. Before each measurement write the expected value/range, reference, instrument/setup and what each possible result would mean. Scope evidence includes probe factor, coupling, timebase, vertical scale, trigger and ground/reference. Logic-analyzer evidence includes channel mapping, threshold, sample rate and decode configuration. Measurements without context can be misleading because bandwidth, loading, resolution, sample rate and probe/reference errors change what is observed.`,
      'For a board that resets only during SPI traffic, write a measurement plan using supply current/DMM, scope and logic analyzer. Explain what hypothesis each instrument tests.',
      ['Correct DMM use','Bench supply current-limit diagnostic','Scope setup and waveform measurements','Logic analyzer sample/threshold/channel/decode setup','Measurement limitations','Instrument chosen from hypothesis, not random probing']),
    S('C4',12,'Career integration: solder/rework workmanship and harness evidence',
      ['C4.1','C4.2','C4.3','C4.4','C4.5','C4.6'],
      `Workmanship is judged by repeatable criteria, not “it looks fine.” Solder evidence distinguishes good wetting from cold/disturbed joints, bridges, insufficient solder and heat damage/lifted pads. Plan rework around ESD, heat, mechanical support, pad/trace condition and the correct removal/installation tool. For low-voltage harnesses, match wire gauge, terminal and die; strip without nicking strands; position conductor and insulation crimp correctly; complete strain relief; verify connector keying/pin numbering/labels; then inspect and test continuity/isolation or a more appropriate functional test. Before/after photos plus component orientation and measurements make the repair auditable. Escalate rather than improvise when pad/trace/connector damage exceeds an approved repair method or could compromise safety/signal integrity.`,
      'Document a connector-pin miswire repair from discovery through retermination and verification, including workmanship checks and the point at which you would escalate rather than improvise.',
      ['Identify solder defects/causes','Plan safe through-hole/SMT rework','Proper strip/crimp/strain relief','Pin/key/label continuity checks','Before/after evidence and measurements','Repair-versus-replace/escalate decision']),
    S('C5',13,'Career integration: reproducible fault isolation and root cause',
      ['C5.1','C5.2','C5.3','C5.4','C5.5','C5.6'],
      `Troubleshooting begins by reproducing and describing the symptom under a controlled setup. Compare expected to actual behavior, form at least two plausible hypotheses, and choose the measurement or controlled perturbation whose possible outcomes separate them. Divide-and-conquer, last-good/first-bad signal tracing, known-good substitution and rail-by-rail checks are tools—not excuses to change multiple variables at once. Root cause is the mechanism that created the failure, not the component you happened to replace. After correction, repeat the original failing case plus nominal, boundary and recovery cases to prove the cause is gone and no new failure was introduced. Controlled fault injection demonstrates that the diagnostic method can actually detect a known failure. A failure report preserves symptom, setup, evidence, hypotheses/tests, root cause, corrective action and verification.`,
      'Take an intermittent sensor fault and write the complete Expected→Observed→Hypotheses→Discriminating Test→Root Cause→Correction→Retest chain, including one safe injected fault.',
      ['Reproduce/define symptom','Use competing hypotheses and discriminating measurement','Apply divide-and-conquer/substitution/tracing without multi-variable changes','Distinguish root cause from symptom','Fault injection and recovery verification','Concise failure report']),
    S('C6',14,'Career integration: C programming as testable technical work',
      ['C6.1','C6.2','C6.3','C6.4','C6.5','C6.6'],
      `C competence means predicting data and control flow. Use explicit integer types and understand signedness/range; apply operator precedence deliberately; structure decisions/loops so termination and boundary cases are clear. Functions use prototypes, parameters, return values and scope to isolate behavior. Arrays/strings occupy contiguous objects with bounds; structs group fields; enums give named states; pointers store addresses and must refer to valid live objects. Bitwise AND/OR/XOR/shifts/masks operate on bit patterns and are central to registers. Common defects include off-by-one indexing, uninitialized state, invalid/dangling/null pointers, integer overflow/truncation and missing bounds checks. Compile with warnings enabled, treat diagnostics as evidence, reproduce the defect, inspect variables/control flow and change one supported cause instead of random edits.`,
      'Write and explain a small C function that updates selected bits in a byte, then identify one bounds error and one pointer-lifetime error in a short example and describe how compiler/debugger evidence would expose them.',
      ['Expressions/control flow','Functions/prototypes/scope','Arrays/strings/structs/enums/pointers and lifetimes','Bitwise masks/shifts','Common defect classes','Warnings and methodical debugging']),
    S('C7',15,'Career integration: embedded C, MCU architecture, and nonblocking design',
      ['C7.1','C7.2','C7.3','C7.4','C7.5','C7.6'],
      `A microcontroller combines CPU, registers, volatile/nonvolatile memory, clock/reset, buses and memory-mapped peripherals. Fixed-width integer types communicate bit width; volatile tells the compiler an object can change outside ordinary code flow (hardware/ISR) but does not make access atomic or thread-safe. Peripheral registers are manipulated with masks and read-modify-write only when the hardware permits it, preserving unrelated bits. Polling repeatedly checks state and can be simplest for slow/noncritical work; interrupts respond asynchronously and are appropriate when latency or CPU use demands it, but shared-state handling must be deliberate. Long blocking delays hide timing and prevent responsiveness. A nonblocking state machine represents mode/state plus events/time, allowing other work to proceed. Separating hardware abstraction/drivers, application state/logic and diagnostics creates seams for testing and fault isolation.`,
      'Design a nonblocking MCU state machine that samples a button, drives an LED pattern and reports status without long delays. Identify which state may be volatile and what belongs in ISR versus application code.',
      ['CPU/register/memory/peripheral/clock/interrupt/bus roles','Fixed-width and volatile use/limits','Mask/read-modify-write preserving unrelated bits','Nonblocking state machine','Polling vs interrupt decision','Layer hardware/application/diagnostic responsibilities']),
    S('C8',16,'Career integration: STM32 bring-up and SWD evidence',
      ['C8.1','C8.2','C8.3','C8.4','C8.5','C8.6'],
      `STM32 bring-up is staged so one bad assumption does not hide another. Select the exact MCU/board, establish clock/boot/debug configuration, map pins and generate initialization, then build/flash a minimal known-good project. Verify a GPIO output in both firmware state and physical voltage; add input/interrupt/timer/ADC only after the baseline is stable. SWD provides halt/step, breakpoints, variables, memory/register views and reset/fault information, letting you distinguish “code never reached this line” from “code says HIGH but the pin is electrically wrong.” Early board checks include supply/current draw, reset state, boot straps, clock source/configuration and debug connectivity. Every fault record names board/revision/configuration, firmware commit/build, debugger observation, measurement, cause and verified fix.`,
      'Bring up one STM32 GPIO from blank project to physical verification and describe how SWD plus DMM/scope evidence separates code-flow, clock/configuration and pin/electrical faults.',
      ['Correct board/clock/pin/generated init','GPIO firmware plus physical verification','SWD halt/step/breakpoint/register use','Timer/ADC/interrupt units/clock assumptions','Current/reset/boot/clock/debug early checks','Reproducible fault evidence with revision/configuration/fix']),
    S('C9',18,'Career integration: UART, I²C, SPI, datasheets, and protocol captures',
      ['C9.1','C9.2','C9.3','C9.4','C9.5','C9.6'],
      `UART requires matching baud/data/parity/stop settings, compatible logic levels, common reference and correctly crossed TX/RX where appropriate. I²C uses SDA/SCL open-drain behavior with pull-ups, START/STOP, address, direction and ACK/NACK; wrong address, missing pull-ups or a stuck-low device are common. SPI uses clock, MOSI, MISO and chip select, with mode defined by clock polarity/phase plus word length/bit order; wrong CPOL/CPHA can shift/corrupt data while the wires still toggle. A datasheet supplies register addresses, reset values, transaction sequence, timing, voltage/pin constraints and expected response. Logic-analyzer evidence must map channels, threshold/sample rate and decoded transaction to the firmware action and expected register result. Diagnose by layer: configuration/code, electrical connection/levels, signal integrity, addressing/select, then protocol sequence.`,
      'Use a sensor datasheet to plan one UART diagnostic and one I²C or SPI register read, including logic-analyzer settings and the evidence that would distinguish firmware, wiring, addressing and protocol failures.',
      ['UART parameter/level/TX-RX diagnosis','I2C open-drain/pull-up/address/ACK/stuck-bus','SPI clock/data/CS/CPOL/CPHA/word configuration','Logic analyzer correlation','Datasheet register/timing/response extraction','Layered failure classification']),
    S('C10',27,'Career integration: Python hardware-test automation and data integrity',
      ['C10.1','C10.2','C10.3','C10.4','C10.5','C10.6'],
      `A hardware-test script should make setup and failure behavior explicit. Open a serial device with named port/settings and timeouts; catch/report connection/read errors rather than hanging forever. Parse messages into structured values with units and reject malformed, missing or out-of-range fields before they enter analysis. Log timestamp, device/firmware ID, setup/configuration, stimulus and raw plus parsed result in a reproducible format such as CSV/JSON. PASS/FAIL logic compares measured values with written limits and reports which criterion failed. Summaries/plots reveal trend, drift, noise and outliers but preserve raw data so visualization cannot hide evidence. Structure code into setup → stimulus → measurement → evaluation → cleanup → reporting so hardware state is left safe even when an exception occurs and each stage can be tested independently.`,
      'Design a Python serial test for a temperature sensor that logs raw/parsed data, rejects malformed packets, applies limits, plots trend, and always performs cleanup on timeout/error.',
      ['Serial settings/timeouts/error handling','Structured parsing and malformed/range rejection','Timestamp/unit/device/configuration logging','Explicit PASS/FAIL limits and reason','Trend/drift/noise/outlier summary','Separate setup/stimulus/measure/evaluate/cleanup/report']),
    S('C11',28,'Career integration: verification, validation, test design, and traceability',
      ['C11.1','C11.2','C11.3','C11.4','C11.5','C11.6'],
      `Verification asks whether a stated requirement was met; validation asks whether the product/system meets the intended user/use need. Characterization measures behavior over ranges without necessarily assigning pass/fail; troubleshooting finds a cause; production test screens units efficiently against controlled criteria. Translate each requirement into setup, calibrated/appropriate instrument, stimulus, expected result/tolerance and evidence. Repeatability requires controlling variables and recording configuration so another technician can reproduce the procedure. Test nominal, boundary and safe fault conditions rather than only the happy path. A result can be PASS, FAIL or INCONCLUSIVE when evidence is insufficient; “looks okay” is not a status. Trace requirement → test case → result → anomaly → corrective action → retest so a reviewer can see exactly what changed and why the final status is defensible.`,
      'Turn one interface requirement into a verification test with nominal, boundary and fault cases, then classify three hypothetical results as pass/fail/inconclusive and preserve full traceability.',
      ['Requirement-to-measurement translation','Differentiate verification/validation/characterization/troubleshooting/production test','Repeatable controlled procedure','Nominal/boundary/fault cases','Pass/fail/inconclusive based on evidence','Requirement-test-result-anomaly-action-retest trace']),
    S('C12',22,'Career integration: Git, command line, lab notes, reports, and technical handoff',
      ['C12.1','C12.2','C12.3','C12.4','C12.5','C12.6'],
      `Engineering evidence must be reconstructable. Use Git commits that describe one coherent change and branches when isolating work is useful; do not rewrite away the history needed to explain a test/fix. A repeatable project structure and basic command-line commands make build/run/log/archive steps explicit. Lab notes include date/objective, hardware/software revision, configuration, instrument/settings, observations, measurements, anomalies and next action. A concise test report states purpose, setup, method, results with units/plots/tables, conclusion against requirements and unresolved risks. When escalating to an engineer, separate observed facts from hypotheses and include measurements, what was already checked and a precise question. Keep filenames, units, screenshots, code, schematics and artifacts consistently versioned so someone else can reproduce the story months later.`,
      'Package one lab result for engineer review: show commit/history pointer, reproducible command/build path, lab note, concise test report, anomaly evidence, and the exact question being escalated.',
      ['Meaningful Git commits/branches','Repeatable command-line/project structure','Complete dated lab notes','Purpose/setup/method/results/conclusion/risks report','Fact-based engineer handoff with precise question','Organized versioned units/files/screenshots/code/schematics/evidence']),
    S('C13',30,'Career integration: portfolio proof, interviews, resumes, and bridge-role decisions',
      ['C13.1','C13.2','C13.3','C13.4','C13.5','C13.6'],
      `A portfolio project is credible when you can state the problem, requirements, architecture, implementation choices, test evidence, one failure/recovery story and final limitation/result. Claim only what you personally did and can defend; do not inflate title, certification, physical skill or engineering authority. In troubleshooting interviews, verbalize expected behavior, hypotheses and the next discriminating measurement rather than guessing a component. Resume bullets name concrete tool/action/result/evidence, not empty adjectives. Evaluate job descriptions by separating true must-haves (safety/shift/authorization/core hardware skill) from learnable tools and preferred items; a bridge role is useful when it provides real electronics/test/validation experience, stable full-time compensation and compatibility with continuing school. Treat application/interview feedback as data: identify recurring technical gaps, improve the relevant project/evidence or interview story, then test the change with future applications.`,
      'Deliver a five-minute project defense and then evaluate one technician/test job posting: identify must-haves vs learnable items, your evidence, missing gaps, and the next repair/application decision.',
      ['Problem-requirements-architecture-implementation-test-failure/recovery-result story','Precise personal contribution','Hypothesis-and-measurement interview reasoning','Concrete resume evidence','Must-have vs learnable bridge-role analysis','Use feedback to choose next technical/portfolio/search repair'])
  ];

  const allSections = [...sections, ...moreSections, ...laterSections, ...careerSections];
  const cetaRows = new Map((A.cetaStandards || []).map(x => [x.code, x]));
  const careerRows = new Map((A.careerStandards || []).map(x => [x.code, x]));
  const byCode = new Map();
  for (const sec of allSections) {
    sec.taskId = `SEM-${String(sec.domain).replace(/[^A-Za-z0-9]/g,'')}-${String(sec.week).padStart(2,'0')}-${String(allSections.indexOf(sec)+1).padStart(3,'0')}`;
    for (const code of sec.codes) {
      if (byCode.has(code)) console.warn('v16.3 semantic duplicate mapping', code);
      byCode.set(code, sec);
    }
  }

  // The generic v16.1 competency clinic remains visible only as historical traceability;
  // it is explicitly not counted as subject teaching after this repair.
  if (C && Array.isArray(C.modules)) for (const mod of C.modules) {
    for (const lesson of (mod.lessons || [])) {
      const d = lesson.instructionalDepth;
      if (d && Array.isArray(d.teaching)) {
        for (const block of d.teaching) {
          if (/^Competency clinic/i.test(block.title || '')) {
            block.title = 'v16.1 traceability checklist — not counted as technical teaching';
            block.text = 'This historical checklist preserves the v16.1 crosswalk but no longer counts as instruction. Use the v16.3 integrated subject-specific teaching and required technical checks for competency evidence.';
          }
        }
      }
    }
  }

  const moduleByWeek = new Map((C?.modules || []).map(m => [Number(m.week), m]));
  for (const sec of allSections) {
    const mod = moduleByWeek.get(sec.week);
    if (!mod) continue;
    const isCareer = String(sec.domain).startsWith('C');
    const lesson = mod.lessons?.[isCareer ? 1 : 0];
    if (!lesson) continue;
    lesson.semanticTeaching = lesson.semanticTeaching || [];
    lesson.semanticTeaching.push({
      taskId: sec.taskId,
      title: sec.title,
      track: isCareer ? 'Career' : 'CETa',
      codes: [...sec.codes],
      teach: sec.teach,
      prompt: sec.prompt,
      required: [...sec.required]
    });
  }

  // Retire the 186 v16.1 auto-filled generic questions. IDs remain in data for saved-history compatibility.
  let retiredV161 = 0;
  for (const q of (A.questions || [])) {
    if (String(q.family || '').startsWith('v161-')) {
      q.retired = true;
      q.masteryEvidence = false;
      q.questionClass = 'retired-v161-semantic-filler';
      q.retirementReason = 'v16.3: generic coverage-fill item did not prove subject-specific knowledge; preserved only for historical ID compatibility.';
      retiredV161++;
    }
  }

  // Make semantic assessment/evidence paths machine-readable and attach them to standard rows.
  const semanticTasks = allSections.map(sec => ({
    id: sec.taskId,
    track: String(sec.domain).startsWith('C') ? 'Career' : 'CETa',
    domain: sec.domain,
    week: sec.week,
    title: sec.title,
    standards: [...sec.codes],
    prompt: sec.prompt,
    requiredElements: [...sec.required],
    assessmentType: 'constructed-response / teach-back / technical evidence',
    masteryRule: 'A response must address every required element with topic-specific reasoning; generic process language does not pass.',
    required: true
  }));
  A.semanticTasks = semanticTasks;

  for (const row of [...(A.cetaStandards || []), ...(A.careerStandards || [])]) {
    const sec = byCode.get(row.code);
    if (!sec) continue;
    row.semanticTeaching = {
      version: '16.3',
      verdict: 'PASS',
      week: sec.week,
      section: sec.title,
      taskId: sec.taskId,
      requiredSubjectKnowledge: sec.required.join('; ')
    };
  }

  // Update v16.1 coverage-matrix rows in-place when present so consumers see the repaired route.
  if (C && Array.isArray(C.coverageMatrix)) {
    for (const row of C.coverageMatrix) {
      const code = row.code || row.standardCode;
      const sec = byCode.get(code);
      if (!sec) continue;
      row.semanticVersion = '16.3';
      row.semanticTeachingVerdict = 'PASS';
      row.semanticTeachingSection = sec.title;
      row.semanticAssessmentTask = sec.taskId;
      row.requiredSubjectKnowledge = sec.required.join('; ');
    }
  }

  if (C) C.meta = {...(C.meta || {}), version:'16.3', semanticRepair:{date:'2026-09-15',cetaRowsMapped:(A.cetaStandards||[]).filter(x=>byCode.has(x.code)).length,careerRowsMapped:(A.careerStandards||[]).filter(x=>byCode.has(x.code)).length,semanticTasks:semanticTasks.length,retiredV161GenericQuestions:retiredV161,policy:'Counts follow semantic validation. Generic v16.1 competency-clinic text is traceability only and generic v16.1 fill questions are retired.'}};
  const activeReviewed = (A.questions || []).filter(q => q.masteryEvidence !== false && q.audit?.status === 'editorially-reviewed');
  const activeCeta = activeReviewed.filter(q => q.track === 'CETa');
  const activeCareer = activeReviewed.filter(q => q.track === 'Career');
  const activeCetaTags = new Set(activeCeta.flatMap(q => q.standards || []).filter(x => String(x).startsWith('CETA:')));
  const activeCareerTags = new Set(activeCareer.flatMap(q => q.standards || []).filter(x => String(x).startsWith('CAREER:')));

  // Restore truthful bank metrics after the v16.1 generated coverage-fill questions are retired.
  // Subject-specific semantic tasks, not generic MCQs, provide complete row-level assessment coverage.
  for (const cov of (A.meta?.coverage || [])) {
    const domain = String(cov.id);
    const domainRows = (A.cetaStandards || []).filter(r => String(r.code).split('.')[0] === domain);
    const domainTags = new Set(domainRows.map(r => `CETA:${r.code}`));
    const domainQuestions = activeCeta.filter(q => (q.standards || []).some(tag => domainTags.has(tag)));
    const directlySampled = domainRows.filter(r => activeCetaTags.has(`CETA:${r.code}`)).map(r => `CETA:${r.code}`);
    cov.practiceItems = domainQuestions.length;
    cov.directlySampled = directlySampled.length;
    cov.objectiveRows = domainRows.length;
    cov.notDirectlySampled = domainRows.filter(r => !activeCetaTags.has(`CETA:${r.code}`)).map(r => `CETA:${r.code}`);
    cov.semanticRows = domainRows.filter(r => byCode.has(r.code)).length;
    cov.semanticAssessment = 'Every row has a required v16.3 subject-specific constructed-response/performance task; direct MCQ counts are shown separately.';
  }

  A.meta = {...(A.meta || {}),
    version:'16.3',
    updated:'2026-09-15',
    gradedQuestionCount: activeReviewed.length,
    orientationQuestionCount: (A.questions || []).filter(q => q.questionClass === 'orientation' || q.masteryEvidence === false && !String(q.family || '').startsWith('v161-')).length,
    audit:{...(A.meta?.audit || {}),date:'2026-09-15',status:'v16.3-integrated-semantic-evidence',structurallyScreened:(A.questions||[]).length,editoriallyReviewed:activeReviewed.length,retiredV161GenericQuestions:retiredV161,semanticTasks:semanticTasks.length,remainingGradedReview:0,note:'223 pre-existing substantive reviewed bank items remain active. The 186 generic v16.1 coverage-fill questions are retired. Complete row-level assessment coverage is supplied by 87 required topic-specific semantic tasks; these are learner-audited constructed responses/performance evidence rather than auto-graded MCQs.'},
    completionAudit:{generatedV161ItemsRetired:retiredV161,activeReviewedBankItems:activeReviewed.length,cetaRowsWithDirectReviewedBankQuestion:(A.cetaStandards||[]).filter(s=>activeCetaTags.has(`CETA:${s.code}`)).length,careerRowsWithDirectReviewedBankQuestion:(A.careerStandards||[]).filter(s=>activeCareerTags.has(`CAREER:${s.code}`)).length,cetaRowsWithRequiredSemanticAssessment:(A.cetaStandards||[]).filter(s=>byCode.has(s.code)).length,careerRowsWithRequiredSemanticAssessment:(A.careerStandards||[]).filter(s=>byCode.has(s.code)).length,cetaRowsTotal:(A.cetaStandards||[]).length,careerRowsTotal:(A.careerStandards||[]).length,policy:'Direct MCQ bank coverage and complete semantic assessment coverage are reported separately. No row is called assessed solely because a generic v16.1 filler question once existed.'},
    semanticRepair:{retiredV161GenericQuestions:retiredV161,taskCount:semanticTasks.length,cetaTaskRows:(A.cetaStandards||[]).filter(x=>byCode.has(x.code)).length,careerTaskRows:(A.careerStandards||[]).filter(x=>byCode.has(x.code)).length,policy:'Every standard is linked to subject-specific teaching and a technical constructed-response/performance task; retired generic items remain only for saved-history compatibility.'}
  };

  window.ALFRED_SEMANTIC_REPAIR = {version:'16.3',sections:allSections,tasks:semanticTasks,byCode:Object.fromEntries([...byCode].map(([code,sec])=>[code,sec.taskId])),retiredV161,activeReviewedBankItems:activeReviewed.length};
})();
